-- sql/2026-10-11_equipements_dd35_drs07_sp-po2.sql
-- SP-PO2 — Import des équipements DD3.5 du DRS 07 (Équipement) : l'arbre des catégories,
-- puis les articles (armes, armures et boucliers, marchandises et services) avec leur
-- description propre. Les mécanismes de jeu restent dans les règles (SP-DRS2) ; les listes
-- des règles sont produites par le tag [[liste:equipement|…]] (SP-PO1).
--
-- Source : ressource « DRS 3.5 » (socle SP-DRS0). Corrections du texte :
-- doc/LOG_CORRECTIONS_DRS07_DRS23.md.
-- Pré-requis : 2026-10-11_equipements_00_schema_sp-po0.sql, 2026-08-25_regles_dd35_socle.sql.
-- Rejouable : les catégories sont mises à jour par slug ; les articles de la source
-- « DRS 3.5 » sont supprimés puis réinsérés (les ajouts faits dans une autre source,
-- dont les suppléments, ne sont pas touchés). Aucun id codé en dur. Pas de DELIMITER.

SET NAMES utf8mb4;

SET @ddver := (SELECT var_id FROM dd_variables WHERE var_cat = 'ruleset' AND var_valeur = 'DD3.5' LIMIT 1);
SET @res   := (SELECT res_id FROM dd_ressources WHERE res_abreviation = 'DRS 3.5' AND res_ruleset_var_id = @ddver LIMIT 1);

START TRANSACTION;

-- ------------------------------------------------------------
-- 1. Catégories
-- ------------------------------------------------------------
