SET @cae_services := (SELECT cae_id FROM dd_categorie_equipement WHERE cae_slug = 'services' AND cae_ruleset_var_id = @ddver);

-- ------------------------------------------------------------
-- 2. Articles
-- ------------------------------------------------------------
DELETE FROM dd_equipements WHERE eqt_res_id = @res AND eqt_ruleset_var_id = @ddver;

-- armes-courantes-mains-nues
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Attaque à mains nues', @cae_armes_courantes_mains_nues, NULL, NULL, NULL, NULL, '{"degats_p":"1d2","degats_m":"1d3","critique":"×2","portee":"—","type":"Contondant","part":"Dégâts non létaux"}', 10, '<p>Un personnage de taille M inflige 1d3 points de dégâts non-létaux à chaque attaque à mains nues, terme générique pouvant désigner un coup de poing, de pied, de tête, etc. Pour un personnage de taille P, ces dégâts ne sont que de 1d2 points. Un moine ou un personnage possédant le don Science du combat à mains nues peut choisir d''infliger des dégâts létaux ou non-létaux à mains nues, au choix du joueur. Les dégâts infligés par ce type d''attaque sont assimilés à ceux qu''occasionnent les armes pour ce qui est des effets donnant des bonus aux dégâts des armes.</p>
<p>Une attaque à mains nues est toujours considérée comme une arme légère. Le don Attaque en finesse permet donc d''ajouter son bonus de Dextérité au jet d''attaque (à la place du bonus de Force) quand on se bat à mains nues.</p>', 1, 0, @res, NULL, @ddver),
  ('Gantelet', @cae_armes_courantes_mains_nues, 200, NULL, 500, NULL, '{"degats_p":"1d2","degats_m":"1d3","critique":"×2","portee":"—","type":"Contondant"}', 20, '<p>Ces épais gants de métal permettent d''infliger des dégâts létaux lorsqu''on se bat à coups de poings (au lieu de non-létaux). Un coup de gantelet est par ailleurs considéré comme une attaque à mains nues. Le prix et le poids indiqués concernent un seul gantelet, pas la paire. Les armures intermédiaires et lourdes sont toutes équipées de gantelets, à l''exception de la cuirasse.</p>', 1, 0, @res, NULL, @ddver);

-- armes-courantes-legeres
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Dague', @cae_armes_courantes_legeres, 200, NULL, 500, NULL, '{"degats_p":"1d3","degats_m":"1d4","critique":"19–20/×2","portee":"3 m","type":"Perforant ou tranchant"}', 10, '<p>Un personnage qui tente de dissimuler une dague sur sa personne bénéficie d''un bonus de +2 sur son test d''Escamotage (voir la description de cette compétence).</p>', 1, 0, @res, NULL, @ddver),
  ('Dague coup-de-poing', @cae_armes_courantes_legeres, 200, NULL, 500, NULL, '{"degats_p":"1d3","degats_m":"1d4","critique":"×3","portee":"—","type":"Perforant"}', 20, NULL, 1, 0, @res, NULL, @ddver),
  ('Gantelet clouté', @cae_armes_courantes_legeres, 500, NULL, 500, NULL, '{"degats_p":"1d3","degats_m":"1d4","critique":"×2","portee":"—","type":"Perforant"}', 30, '<p>Il est impossible d''être désarmé lorsqu''on se bat à coups de gantelets cloutés. Le coût et le poids indiqués s''entendent à l''unité, pas à la paire. Un coup de gantelet clouté est considéré comme une attaque avec arme.</p>', 1, 0, @res, NULL, @ddver),
  ('Masse d''armes légère', @cae_armes_courantes_legeres, 500, NULL, 2000, NULL, '{"degats_p":"1d4","degats_m":"1d6","critique":"×2","portee":"—","type":"Contondant"}', 40, NULL, 1, 0, @res, NULL, @ddver),
  ('Serpe', @cae_armes_courantes_legeres, 600, NULL, 1000, NULL, '{"degats_p":"1d4","degats_m":"1d6","critique":"×2","portee":"—","type":"Tranchant"}', 50, '<p>Cette arme permet de tenter des crocs-en-jambe. Si le personnage échoue dans sa tentative, il peut lâcher son arme pour éviter que le croc-en-jambe ne se retourne contre lui.</p>', 1, 0, @res, NULL, @ddver);

-- armes-courantes-une-main
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Épieu', @cae_armes_courantes_une_main, 100, NULL, 1500, NULL, '{"degats_p":"1d4","degats_m":"1d6","critique":"×2","portee":"6 m","type":"Perforant"}', 10, '<p>Cette arme peut être jetée.</p>', 1, 0, @res, NULL, @ddver),
  ('Gourdin', @cae_armes_courantes_une_main, NULL, NULL, 1500, NULL, '{"degats_p":"1d4","degats_m":"1d6","critique":"×2","portee":"3 m","type":"Contondant"}', 20, NULL, 1, 0, @res, NULL, @ddver),
  ('Masse d''armes lourde', @cae_armes_courantes_une_main, 1200, NULL, 4000, NULL, '{"degats_p":"1d6","degats_m":"1d8","critique":"×2","portee":"—","type":"Contondant"}', 30, NULL, 1, 0, @res, NULL, @ddver),
  ('Morgenstern', @cae_armes_courantes_une_main, 800, NULL, 3000, NULL, '{"degats_p":"1d6","degats_m":"1d8","critique":"×2","portee":"—","type":"Contondant et perforant"}', 40, NULL, 1, 0, @res, NULL, @ddver);

-- armes-courantes-deux-mains
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Bâton', @cae_armes_courantes_deux_mains, NULL, NULL, 2000, NULL, '{"degats_p":"1d4/1d4","degats_m":"1d6/1d6","critique":"×2","portee":"—","type":"Contondant","part":"Arme double"}', 10, '<p>Le bâton est une arme double. Il est possible de s''en servir comme si l''on se battait avec deux armes mais, dans ce cas, le personnage encourt les malus habituels du combat à deux armes, comme s''il utilisait une arme à une main et une arme légère. Une créature maniant cette arme à une main ne peut pas s''en servir comme d''une arme double ; elle doit choisir l''une des deux têtes et s''y tenir pour le round.</p>
<p>Le bâton est une arme de moine, ce qui lui permet d''utiliser certains de ses pouvoirs lorsqu''il combat à l''aide de cette arme.</p>', 1, 0, @res, NULL, @ddver),
  ('Lance', @cae_armes_courantes_deux_mains, 200, NULL, 3000, NULL, '{"degats_p":"1d6","degats_m":"1d8","critique":"×3","portee":"6 m","type":"Perforant"}', 20, '<p>Cette arme peut être jetée. À condition d''utiliser une action pour préparer une réception de charge, la lance inflige des dégâts doublés à un adversaire qui charge.</p>', 1, 0, @res, NULL, @ddver),
  ('Pique', @cae_armes_courantes_deux_mains, 500, NULL, 4500, NULL, '{"degats_p":"1d6","degats_m":"1d8","critique":"×3","portee":"—","type":"Perforant","part":"Arme à allonge"}', 30, '<p>La pique est une arme à allonge, qui permet d''attaquer des adversaires distants de 3 mètres, mais pas ceux adjacents. À condition d''utiliser une action pour préparer une réception de charge, la pique inflige des dégâts doublés à un adversaire qui charge.</p>', 1, 0, @res, NULL, @ddver);

-- armes-courantes-distance
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Arbalète légère', @cae_armes_courantes_distance, 3500, NULL, 2000, NULL, '{"degats_p":"1d6","degats_m":"1d8","critique":"19–20/×2","portee":"24 m","type":"Perforant"}', 10, '<p>Une arbalète légère se tend à l''aide d''un levier. Recharger une arbalète légère est une action de mouvement provoquant une attaque d''opportunité.</p>
<p>Une arbalète légère s''utilise habituellement à deux mains. Il est cependant possible de l''utiliser (mais pas de la recharger) d''une seule main, avec un malus de –2 sur le jet d''attaque. On peut même utiliser une arbalète légère dans chaque main, mais avec des malus correspondant au combat à deux armes légères. Ce malus se cumule avec celui encouru pour tirer à une main.</p>', 1, 0, @res, NULL, @ddver),
  ('Arbalète lourde', @cae_armes_courantes_distance, 5000, NULL, 4000, NULL, '{"degats_p":"1d8","degats_m":"1d10","critique":"19–20/×2","portee":"36 m","type":"Perforant"}', 20, '<p>Une arbalète lourde se tend à l''aide d''une manivelle. Recharger une arbalète lourde est une action complexe provoquant une attaque d''opportunité.</p>
<p>Une arbalète lourde s''utilise habituellement à deux mains. Il est cependant possible de l''utiliser, mais pas de la recharger, d''une seule main, avec un malus de –4 sur le jet d''attaque. On peut même utiliser une arbalète lourde dans chaque main, mais avec des malus correspondant au combat à deux armes à une main. Ce malus se cumule avec celui encouru pour tirer à une main.</p>', 1, 0, @res, NULL, @ddver),
  ('Carreaux (10)', @cae_armes_courantes_distance, 100, NULL, 500, NULL, '{"degats_p":"—","degats_m":"—","critique":"—","portee":"—","type":"—"}', 30, '<p>Utilisé en tant qu''arme de corps à corps, le carreau est une arme légère improvisée (malus de –4 sur les jets d''attaque) qui inflige autant de dégâts qu''une dague de sa taille (critique ×2). Les carreaux sont vendus par 10 (ou 5 seulement pour une arbalète à répétition) dans un carquois de bois. Un carreau atteignant sa cible n''est pas réutilisable. Si le coup est raté, le projectile a 50 % de chances de se casser ou de se perdre.</p>', 1, 0, @res, NULL, @ddver),
  ('Dard', @cae_armes_courantes_distance, 50, NULL, 250, NULL, '{"degats_p":"1d3","degats_m":"1d4","critique":"×2","portee":"6 m","type":"Perforant"}', 40, NULL, 1, 0, @res, NULL, @ddver),
  ('Fronde', @cae_armes_courantes_distance, NULL, NULL, NULL, NULL, '{"degats_p":"1d3","degats_m":"1d4","critique":"×2","portee":"15 m","type":"Contondant"}', 50, '<p>Le modificateur de Force d''un personnage s''applique aux jets de dégâts d''une fronde, comme si elle était une arme de jet. Il est possible d''utiliser, mais pas de recharger, une fronde d''une seule main. Recharger une fronde est une action de mouvement qui nécessite deux mains et provoque une attaque d''opportunité.</p>
<p>Il est également possible de lancer des pierres ordinaires avec une fronde, mais ces projectiles sont moins denses et moins profilés que les billes, ce qui réduit leurs dégâts, comme si elles étaient destinées à des créatures d''une catégorie de taille inférieure, et leur efficacité (malus de –1 au jet d''attaque).</p>', 1, 0, @res, NULL, @ddver),
  ('Billes de fronde (10)', @cae_armes_courantes_distance, 10, NULL, 2500, NULL, '{"degats_p":"—","degats_m":"—","critique":"—","portee":"—","type":"—"}', 60, '<p>Elles sont en plomb, ce qui les rend bien plus lourdes que des pierres de même taille. Elles sont vendues par 10 dans une bourse de cuir. Une bille atteignant sa cible n''est pas réutilisable. Si le coup est raté, elle a 50 % de chances de se casser ou de se perdre.</p>', 1, 0, @res, NULL, @ddver),
  ('Javeline', @cae_armes_courantes_distance, 100, NULL, 1000, NULL, '{"degats_p":"1d4","degats_m":"1d6","critique":"×2","portee":"9 m","type":"Perforant"}', 70, '<p>On peut s''en servir au corps à corps, mais son efficacité est alors fortement réduite. On considère qu''un personnage l''utilisant de la sorte ne sait pas la manier (–4 au jet d''attaque).</p>', 1, 0, @res, NULL, @ddver);

-- armes-de-guerre-legeres
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Armure à pointes', @cae_armes_de_guerre_legeres, NULL, 'spécial', NULL, 'spécial', '{"degats_p":"1d4","degats_m":"1d6","critique":"×2","portee":"—","type":"Perforant"}', 10, '<p>Une armure garnie de pointes permet d''infliger des dégâts pendant une lutte ou lors d''une attaque à part entière. Voir la section sur les armures (<em>Pointes pour armure</em>).</p>', 1, 0, @res, NULL, @ddver),
  ('Épée courte', @cae_armes_de_guerre_legeres, 1000, NULL, 1000, NULL, '{"degats_p":"1d4","degats_m":"1d6","critique":"19–20/×2","portee":"—","type":"Perforant"}', 20, NULL, 1, 0, @res, NULL, @ddver),
  ('Hache de lancer', @cae_armes_de_guerre_legeres, 800, NULL, 2000, NULL, '{"degats_p":"1d4","degats_m":"1d6","critique":"×2","portee":"3 m","type":"Tranchant"}', 30, NULL, 1, 0, @res, NULL, @ddver),
  ('Hachette', @cae_armes_de_guerre_legeres, 600, NULL, 1500, NULL, '{"degats_p":"1d4","degats_m":"1d6","critique":"×3","portee":"—","type":"Tranchant"}', 40, NULL, 1, 0, @res, NULL, @ddver),
  ('Kukri', @cae_armes_de_guerre_legeres, 800, NULL, 1000, NULL, '{"degats_p":"1d3","degats_m":"1d4","critique":"18–20/×2","portee":"—","type":"Tranchant"}', 50, NULL, 1, 0, @res, NULL, @ddver),
  ('Marteau léger', @cae_armes_de_guerre_legeres, 100, NULL, 1000, NULL, '{"degats_p":"1d3","degats_m":"1d4","critique":"×2","portee":"6 m","type":"Contondant"}', 60, NULL, 1, 0, @res, NULL, @ddver),
  ('Matraque', @cae_armes_de_guerre_legeres, 100, NULL, 1000, NULL, '{"degats_p":"1d4","degats_m":"1d6","critique":"×2","portee":"—","type":"Contondant","part":"Dégâts non létaux"}', 70, NULL, 1, 0, @res, NULL, @ddver),
  ('Pic de guerre léger', @cae_armes_de_guerre_legeres, 400, NULL, 1500, NULL, '{"degats_p":"1d3","degats_m":"1d4","critique":"×4","portee":"—","type":"Perforant"}', 80, NULL, 1, 0, @res, NULL, @ddver),
  ('Rondache', @cae_armes_de_guerre_legeres, NULL, 'spécial', NULL, 'spécial', '{"degats_p":"1d2","degats_m":"1d3","critique":"×2","portee":"—","type":"Contondant"}', 90, '<p>On peut donner des coups de bouclier au lieu de l''utiliser pour se défendre. Voir la section sur les armures (<em>Rondache en bois ou en acier</em>).</p>', 1, 0, @res, NULL, @ddver),
  ('Rondache à pointes', @cae_armes_de_guerre_legeres, NULL, 'spécial', NULL, 'spécial', '{"degats_p":"1d3","degats_m":"1d4","critique":"×2","portee":"—","type":"Perforant"}', 100, '<p>On peut donner des coups de bouclier à pointes au lieu de l''utiliser pour se défendre. Voir la section sur les armures (<em>Pointes pour bouclier</em>).</p>', 1, 0, @res, NULL, @ddver);

-- armes-de-guerre-une-main
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Cimeterre', @cae_armes_de_guerre_une_main, 1500, NULL, 2000, NULL, '{"degats_p":"1d4","degats_m":"1d6","critique":"18–20/×2","portee":"—","type":"Tranchant"}', 10, NULL, 1, 0, @res, NULL, @ddver),
  ('Écu', @cae_armes_de_guerre_une_main, NULL, 'spécial', NULL, 'spécial', '{"degats_p":"1d3","degats_m":"1d4","critique":"×2","portee":"—","type":"Contondant"}', 20, '<p>On peut donner des coups de bouclier au lieu de l''utiliser pour se défendre. Voir la section sur les armures (<em>Écu en bois ou en acier</em>).</p>', 1, 0, @res, NULL, @ddver),
  ('Écu à pointes', @cae_armes_de_guerre_une_main, NULL, 'spécial', NULL, 'spécial', '{"degats_p":"1d4","degats_m":"1d6","critique":"×2","portee":"—","type":"Perforant"}', 30, '<p>On peut donner des coups de bouclier à pointes au lieu de l''utiliser pour se défendre. Voir la section sur les armures (<em>Pointes pour bouclier</em>).</p>', 1, 0, @res, NULL, @ddver),
  ('Épée longue', @cae_armes_de_guerre_une_main, 1500, NULL, 2000, NULL, '{"degats_p":"1d6","degats_m":"1d8","critique":"19–20/×2","portee":"—","type":"Tranchant"}', 40, NULL, 1, 0, @res, NULL, @ddver),
  ('Fléau d''armes léger', @cae_armes_de_guerre_une_main, 800, NULL, 2500, NULL, '{"degats_p":"1d6","degats_m":"1d8","critique":"×2","portee":"—","type":"Contondant"}', 50, '<p>Le fléau d''armes confère un bonus de +2 au jet d''attaque opposé lorsque l''on tente de désarmer son adversaire (ainsi qu''au jet permettant au personnage de ne pas se retrouver lui-même désarmé en cas d''échec de sa tentative).</p>
<p>Cette arme permet de tenter des crocs-en-jambe. Si le personnage échoue dans sa tentative, il peut lâcher son arme pour éviter que le croc-en-jambe ne se retourne contre lui.</p>', 1, 0, @res, NULL, @ddver),
  ('Hache d''armes', @cae_armes_de_guerre_une_main, 1000, NULL, 3000, NULL, '{"degats_p":"1d6","degats_m":"1d8","critique":"×3","portee":"—","type":"Tranchant"}', 60, NULL, 1, 0, @res, NULL, @ddver),
  ('Marteau de guerre', @cae_armes_de_guerre_une_main, 1200, NULL, 2500, NULL, '{"degats_p":"1d6","degats_m":"1d8","critique":"×3","portee":"—","type":"Contondant"}', 70, NULL, 1, 0, @res, NULL, @ddver),
  ('Pic de guerre lourd', @cae_armes_de_guerre_une_main, 800, NULL, 3000, NULL, '{"degats_p":"1d4","degats_m":"1d6","critique":"×4","portee":"—","type":"Perforant"}', 80, NULL, 1, 0, @res, NULL, @ddver),
  ('Rapière', @cae_armes_de_guerre_une_main, 2000, NULL, 1000, NULL, '{"degats_p":"1d4","degats_m":"1d6","critique":"18–20/×2","portee":"—","type":"Perforant"}', 90, '<p>Le don Attaque en finesse permet d''ajouter son bonus de Dextérité au jet d''attaque (à la place du bonus de Force) quand on utilise une rapière destinée à une créature de sa taille, bien que ce ne soit pas une arme légère. Il est impossible de tenir une rapière à deux mains pour multiplier par 1,5 son bonus de Force aux dégâts.</p>', 1, 0, @res, NULL, @ddver),
  ('Trident', @cae_armes_de_guerre_une_main, 1500, NULL, 2000, NULL, '{"degats_p":"1d6","degats_m":"1d8","critique":"×2","portee":"3 m","type":"Perforant"}', 100, '<p>Cette arme peut être jetée. À condition d''utiliser une action pour préparer une réception de charge, le trident inflige des dégâts doublés à un adversaire qui charge.</p>', 1, 0, @res, NULL, @ddver);

-- armes-de-guerre-deux-mains
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Cimeterre à deux mains', @cae_armes_de_guerre_deux_mains, 7500, NULL, 4000, NULL, '{"degats_p":"1d6","degats_m":"2d4","critique":"18–20/×2","portee":"—","type":"Tranchant"}', 10, NULL, 1, 0, @res, NULL, @ddver),
  ('Corsèque', @cae_armes_de_guerre_deux_mains, 1000, NULL, 6000, NULL, '{"degats_p":"1d6","degats_m":"2d4","critique":"×3","portee":"—","type":"Perforant","part":"Arme à allonge"}', 20, '<p>La corsèque est une arme à allonge, qui permet d''attaquer des adversaires distants de 3 mètres. Par contre, il est impossible de l''utiliser contre un ennemi adjacent.</p>
<p>Elle confère un bonus de +2 au jet d''attaque opposé lorsque l''on tente de désarmer son adversaire (ainsi qu''au jet permettant au personnage de ne pas se retrouver lui-même désarmé en cas d''échec de sa tentative).</p>', 1, 0, @res, NULL, @ddver),
  ('Coutille', @cae_armes_de_guerre_deux_mains, 800, NULL, 5000, NULL, '{"degats_p":"1d8","degats_m":"1d10","critique":"×3","portee":"—","type":"Tranchant","part":"Arme à allonge"}', 30, '<p>La coutille est une arme à allonge, qui permet d''attaquer des adversaires distants de 3 mètres. Par contre, il est impossible de l''utiliser contre un ennemi adjacent.</p>', 1, 0, @res, NULL, @ddver),
  ('Épée à deux mains', @cae_armes_de_guerre_deux_mains, 5000, NULL, 4000, NULL, '{"degats_p":"1d10","degats_m":"2d6","critique":"19–20/×2","portee":"—","type":"Tranchant"}', 40, NULL, 1, 0, @res, NULL, @ddver),
  ('Faux', @cae_armes_de_guerre_deux_mains, 1800, NULL, 5000, NULL, '{"degats_p":"1d6","degats_m":"2d4","critique":"×4","portee":"—","type":"Perforant ou tranchant"}', 50, '<p>Une faux permet de tenter des crocs-en-jambe. Si le personnage échoue dans sa tentative, il peut lâcher son arme pour éviter que le croc-en-jambe ne se retourne contre lui.</p>', 1, 0, @res, NULL, @ddver),
  ('Fléau d''armes lourd', @cae_armes_de_guerre_deux_mains, 1500, NULL, 5000, NULL, '{"degats_p":"1d8","degats_m":"1d10","critique":"19–20/×2","portee":"—","type":"Contondant"}', 60, '<p>Le fléau d''armes confère un bonus de +2 au jet d''attaque opposé lorsque l''on tente de désarmer son adversaire (ainsi qu''au jet permettant au personnage de ne pas se retrouver lui-même désarmé en cas d''échec de sa tentative).</p>
<p>Cette arme permet de tenter des crocs-en-jambe. Si le personnage échoue dans sa tentative, il peut lâcher son arme pour éviter que le croc-en-jambe ne se retourne contre lui.</p>', 1, 0, @res, NULL, @ddver),
  ('Grande hache', @cae_armes_de_guerre_deux_mains, 2000, NULL, 6000, NULL, '{"degats_p":"1d10","degats_m":"1d12","critique":"×3","portee":"—","type":"Tranchant"}', 70, NULL, 1, 0, @res, NULL, @ddver),
  ('Guisarme', @cae_armes_de_guerre_deux_mains, 900, NULL, 6000, NULL, '{"degats_p":"1d6","degats_m":"2d4","critique":"×3","portee":"—","type":"Tranchant","part":"Arme à allonge"}', 80, '<p>La guisarme est une arme à allonge, qui permet d''attaquer des adversaires distants de 3 mètres. Par contre, il est impossible de l''utiliser contre un ennemi adjacent.</p>
<p>La guisarme permet de tenter des crocs-en-jambe. Si le personnage échoue dans sa tentative, il peut lâcher son arme pour éviter que le croc-en-jambe ne se retourne contre lui.</p>', 1, 0, @res, NULL, @ddver),
  ('Hallebarde', @cae_armes_de_guerre_deux_mains, 1000, NULL, 6000, NULL, '{"degats_p":"1d8","degats_m":"1d10","critique":"×3","portee":"—","type":"Perforant ou tranchant","part":"Arme à allonge"}', 90, '<p>À condition d''utiliser une action pour préparer une réception de charge, la hallebarde inflige des dégâts doublés à un adversaire qui charge.</p>
<p>La hallebarde permet de tenter des crocs-en-jambe. Si le personnage échoue dans sa tentative, il peut lâcher son arme pour éviter que le croc-en-jambe ne se retourne contre lui.</p>', 1, 0, @res, NULL, @ddver),
  ('Lance d''arçon', @cae_armes_de_guerre_deux_mains, 1000, NULL, 5000, NULL, '{"degats_p":"1d6","degats_m":"1d8","critique":"×3","portee":"—","type":"Perforant","part":"Arme à allonge"}', 100, '<p>Une lance d''arçon, ou de cavalier, cause des dégâts doublés lors d''une charge montée. La lance d''arçon est une arme à allonge, qui permet d''attaquer des adversaires distants de 3 mètres, mais pas ceux adjacents.</p>
<p>Un personnage monté peut tenir une lance à une main.</p>', 1, 0, @res, NULL, @ddver),
  ('Massue', @cae_armes_de_guerre_deux_mains, 500, NULL, 4000, NULL, '{"degats_p":"1d8","degats_m":"1d10","critique":"×2","portee":"—","type":"Contondant"}', 110, NULL, 1, 0, @res, NULL, @ddver);

-- armes-de-guerre-distance
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Arc court', @cae_armes_de_guerre_distance, 3000, NULL, 1000, NULL, '{"degats_p":"1d4","degats_m":"1d6","critique":"×3","portee":"18 m","type":"Perforant"}', 10, '<p>Quelle que soit sa taille, un arc ne peut être utilisé qu''à deux mains. On peut se servir d''un arc court à cheval. Un malus de Force s''applique aux jets de dégâts des arcs courts, mais un bonus de Force ne s''applique pas avec un arc court ordinaire (il faut un arc court composite spécial, voir ci-dessous).</p>', 1, 0, @res, NULL, @ddver),
  ('Arc court composite', @cae_armes_de_guerre_distance, 7500, NULL, 1000, NULL, '{"degats_p":"1d4","degats_m":"1d6","critique":"×3","portee":"21 m","type":"Perforant"}', 20, '<p>Un arc ne peut être utilisé qu''à deux mains, quelle que soit sa taille. Tous les arcs composites sont fabriqués pour une certaine valeur de Force (c''est-à-dire un modificateur de Force minimal pour l''utiliser correctement). Si le bonus de Force du personnage est inférieur à celui de l''arc composite, il ne peut l''utiliser efficacement et subit un malus de –2 sur les jets d''attaque. Un arc composite ordinaire nécessite un modificateur de Force de +0 pour être utilisé avec compétence. Les arcs composites peuvent être fabriqués avec un rang de Force plus élevé pour tirer parti d''une valeur de Force au-dessus de la moyenne. Cela permet alors à un personnage d''appliquer son bonus de Force aux jets de dégâts, dans la limite du bonus indiqué pour l''arc.</p>
<p>On peut se servir d''un arc court composite à cheval. Chaque point de bonus de Force ajouté à un arc augmente son prix de +75 po. Pour ce qui concerne la formation à leur maniement et les dons similaires, les arcs courts ordinaires et les arcs courts composites sont considérés comme étant la même arme.</p>', 1, 0, @res, NULL, @ddver),
  ('Arc long', @cae_armes_de_guerre_distance, 7500, NULL, 1500, NULL, '{"degats_p":"1d6","degats_m":"1d8","critique":"×3","portee":"30 m","type":"Perforant"}', 30, '<p>Quelle que soit sa taille, un arc ne peut être utilisé qu''à deux mains. L''arc long, ou grand arc, est trop peu maniable pour que l''on puisse s''en servir à cheval. Un malus de Force s''applique aux jets de dégâts des arcs longs, mais un bonus de Force ne s''applique pas avec un arc long ordinaire (il faut un arc long composite spécial, voir ci-dessous).</p>', 1, 0, @res, NULL, @ddver),
  ('Arc long composite', @cae_armes_de_guerre_distance, 10000, NULL, 1500, NULL, '{"degats_p":"1d6","degats_m":"1d8","critique":"×3","portee":"33 m","type":"Perforant"}', 40, '<p>Un arc ne peut être utilisé qu''à deux mains, quelle que soit sa taille. Tous les arcs composites sont fabriqués pour une certaine valeur de Force (c''est-à-dire un modificateur de Force minimal pour l''utiliser correctement). Si le bonus de Force du personnage est inférieur à celui de l''arc composite, il ne peut l''utiliser efficacement et subit un malus de –2 sur les jets d''attaque. Un arc composite ordinaire nécessite un modificateur de Force de +0 pour être utilisé avec compétence. Les arcs composites peuvent être fabriqués avec un rang de Force plus élevé pour tirer parti d''une valeur de Force au-dessus de la moyenne. Cela permet alors à un personnage d''appliquer son bonus de Force aux jets de dégâts, dans la limite du bonus indiqué pour l''arc.</p>
<p>Un arc long composite peut être utilisé par un cavalier monté. Chaque point de bonus de Force ajouté à un arc augmente son prix de +100 po. Pour ce qui concerne la formation à leur maniement et les dons similaires, les arcs longs ordinaires et les arcs longs composites sont considérés comme étant la même arme.</p>', 1, 0, @res, NULL, @ddver),
  ('Flèches (20)', @cae_armes_de_guerre_distance, 100, NULL, 1500, NULL, '{"degats_p":"—","degats_m":"—","critique":"—","portee":"—","type":"—"}', 50, '<p>Utilisée en tant qu''arme de corps à corps, la flèche est une arme légère improvisée (malus de –4 sur les jets d''attaque) qui inflige autant de dégâts qu''une dague de sa taille. Les flèches sont vendues par 20 dans un carquois de cuir. Une flèche atteignant sa cible n''est pas réutilisable. Si le coup est raté, elle a 50 % de chances de se casser ou de se perdre.</p>', 1, 0, @res, NULL, @ddver);

-- armes-exotiques-legeres
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Kama', @cae_armes_exotiques_legeres, 200, NULL, 1000, NULL, '{"degats_p":"1d4","degats_m":"1d6","critique":"×2","portee":"—","type":"Tranchant"}', 10, '<p>Cette arme est une arme de moine, ce qui lui permet d''utiliser certains de ses pouvoirs lorsqu''il combat à l''aide de cette arme.</p>
<p>Cette arme permet de tenter des crocs-en-jambe. Si le personnage échoue dans sa tentative, il peut lâcher son arme pour éviter que le croc-en-jambe ne se retourne contre lui.</p>', 1, 0, @res, NULL, @ddver),
  ('Nunchaku', @cae_armes_exotiques_legeres, 200, NULL, 1000, NULL, '{"degats_p":"1d4","degats_m":"1d6","critique":"×2","portee":"—","type":"Contondant"}', 20, '<p>Cette arme est une arme de moine, ce qui lui permet d''utiliser certains de ses pouvoirs lorsqu''il combat à l''aide de cette arme.</p>
<p>Cette arme confère un bonus de +2 au jet d''attaque opposé lorsque l''on tente de désarmer son adversaire (ainsi qu''au jet permettant au personnage de ne pas se retrouver lui-même désarmé en cas d''échec de sa tentative).</p>', 1, 0, @res, NULL, @ddver),
  ('Sai', @cae_armes_exotiques_legeres, 100, NULL, 500, NULL, '{"degats_p":"1d3","degats_m":"1d4","critique":"×2","portee":"—","type":"Contondant"}', 30, '<p>Le sai confère un bonus de +4 au jet d''attaque opposé lorsque l''on tente de désarmer son adversaire (ainsi qu''au jet permettant au personnage de ne pas se retrouver lui-même désarmé en cas d''échec de sa tentative).</p>
<p>Cette arme est une arme de moine, ce qui lui permet d''utiliser certains de ses pouvoirs lorsqu''il combat à l''aide de cette arme.</p>', 1, 0, @res, NULL, @ddver),
  ('Siangham', @cae_armes_exotiques_legeres, 300, NULL, 500, NULL, '{"degats_p":"1d4","degats_m":"1d6","critique":"×2","portee":"—","type":"Perforant"}', 40, '<p>Le siangham est une arme de moine, ce qui lui permet d''utiliser certains de ses pouvoirs lorsqu''il combat à l''aide de cette arme. Un siangham ne peut servir au corps à corps.</p>', 1, 0, @res, NULL, @ddver);

-- armes-exotiques-une-main
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Épée bâtarde', @cae_armes_exotiques_une_main, 3500, NULL, 3000, NULL, '{"degats_p":"1d8","degats_m":"1d10","critique":"19–20/×2","portee":"—","type":"Tranchant"}', 10, '<p>Elle est trop grande pour être utilisée à une main sans entraînement particulier, ce qui explique qu''elle soit rangée dans la catégorie des armes exotiques. Un personnage peut l''utiliser comme arme de guerre s''il la manie à deux mains.</p>', 1, 0, @res, NULL, @ddver),
  ('Fouet', @cae_armes_exotiques_une_main, 100, NULL, 1000, NULL, '{"degats_p":"1d2","degats_m":"1d3","critique":"×2","portee":"—","type":"Tranchant","part":"Arme à allonge, dégâts non létaux"}', 20, '<p>Le fouet inflige des dégâts non-létaux. Il est incapable de toucher la moindre créature bénéficiant d''un bonus d''armure de +1 ou plus, ou d''un bonus d''armure naturelle au moins égal à +3. Un fouet est considéré comme une arme à allonge procurant une allonge de 4,50 mètres, mais qui ne permet pas de menacer la zone dans laquelle il permet d''attaquer. De plus, contrairement aux autres armes de ce type, on peut s''en servir contre un ennemi adjacent ou situé à 3 mètres.</p>
<p>Attaquer avec un fouet provoque une attaque d''opportunité, comme pour une arme à distance.</p>
<p>Cette arme permet de tenter des crocs-en-jambe. Si le personnage échoue dans sa tentative, il peut lâcher son arme pour éviter que le croc-en-jambe ne se retourne contre lui.</p>
<p>Cette arme confère un bonus de +2 au jet d''attaque opposé lorsque l''on tente de désarmer son adversaire (ainsi qu''au jet permettant au personnage de ne pas se retrouver lui-même désarmé en cas d''échec de sa tentative).</p>
<p>Le don Attaque en finesse permet d''ajouter son bonus de Dextérité au jet d''attaque (à la place du bonus de Force) quand on utilise un fouet, et cela bien que ce ne soit pas une arme légère.</p>', 1, 0, @res, NULL, @ddver),
  ('Hache de guerre naine', @cae_armes_exotiques_une_main, 3000, NULL, 4000, NULL, '{"degats_p":"1d8","degats_m":"1d10","critique":"×3","portee":"—","type":"Tranchant"}', 30, '<p>Cette lourde hache est trop volumineuse pour être utilisée à une main sans entraînement particulier. Pour les nains, qui connaissent bien cette arme, c''est une arme de guerre. Mais pour toutes les autres races, c''est une arme exotique si elle est maniée à une main, ou une arme de guerre si elle est maniée à deux mains.</p>', 1, 0, @res, NULL, @ddver);

-- armes-exotiques-deux-mains
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Chaîne cloutée', @cae_armes_exotiques_deux_mains, 2500, NULL, 5000, NULL, '{"degats_p":"1d6","degats_m":"2d4","critique":"×2","portee":"—","type":"Perforant","part":"Arme à allonge"}', 10, '<p>La chaîne cloutée est une arme à allonge, qui permet d''attaquer des adversaires se trouvant à 3 mètres de distance. De plus, contrairement aux autres armes de ce type, on peut s''en servir contre un ennemi adjacent.</p>
<p>Il est possible de l''utiliser pour faire un croc-en-jambe. Si le personnage échoue dans sa tentative, il peut lâcher son arme pour éviter que le croc-en-jambe ne se retourne contre lui.</p>
<p>La chaîne cloutée confère également un bonus de +2 au jet d''attaque opposé lorsque l''on tente de désarmer son adversaire (ainsi qu''au jet permettant au personnage de ne pas se retrouver lui-même désarmé en cas d''échec de sa tentative).</p>
<p>Le don Attaque en finesse permet d''ajouter son bonus de Dextérité au jet d''attaque (à la place du bonus de Force) quand on utilise une chaîne cloutée, et cela bien que ce ne soit pas une arme légère.</p>', 1, 0, @res, NULL, @ddver),
  ('Double-lame', @cae_armes_exotiques_deux_mains, 10000, NULL, 5000, NULL, '{"degats_p":"1d6/1d6","degats_m":"1d8/1d8","critique":"19–20/×2","portee":"—","type":"Tranchant","part":"Arme double"}', 20, '<p>Cette arme étrange est une arme double. Il est possible de s''en servir comme si l''on se battait avec deux armes mais, dans ce cas, le personnage encourt les malus habituels du combat à deux armes, comme s''il utilisait une arme à une main et une arme légère. Une créature maniant cette arme à une main ne peut pas s''en servir comme d''une arme double ; elle doit choisir l''une des deux têtes et s''y tenir pour le round.</p>', 1, 0, @res, NULL, @ddver),
  ('Fléau double', @cae_armes_exotiques_deux_mains, 9000, NULL, 5000, NULL, '{"degats_p":"1d6/1d6","degats_m":"1d8/1d8","critique":"×2","portee":"—","type":"Contondant","part":"Arme double"}', 30, '<p>Comme son nom l''indique, ce fléau est une arme double. Il est possible de s''en servir comme si l''on se battait avec deux armes mais, dans ce cas, le personnage encourt les malus habituels du combat à deux armes, comme s''il utilisait une arme à une main et une arme légère. Une créature maniant cette arme à une main ne peut pas s''en servir comme d''une arme double ; elle doit choisir l''une des deux têtes et s''y tenir pour le round.</p>
<p>Cette arme confère un bonus de +2 au jet d''attaque opposé lorsque l''on tente de désarmer son adversaire (ainsi qu''au jet permettant au personnage de ne pas se retrouver lui-même désarmé en cas d''échec de sa tentative).</p>
<p>Cette arme permet de tenter des crocs-en-jambe. Si le personnage échoue dans sa tentative, il peut lâcher son arme pour éviter que le croc-en-jambe ne se retourne contre lui.</p>', 1, 0, @res, NULL, @ddver),
  ('Hache double orque', @cae_armes_exotiques_deux_mains, 6000, NULL, 7500, NULL, '{"degats_p":"1d6/1d6","degats_m":"1d8/1d8","critique":"×3","portee":"—","type":"Tranchant","part":"Arme double"}', 40, '<p>La hache double orque est une arme double. Il est possible de s''en servir comme si l''on se battait avec deux armes mais, dans ce cas, le personnage encourt les malus habituels du combat à deux armes, comme s''il utilisait une arme à une main et une arme légère. Une créature maniant cette arme à une main ne peut pas s''en servir comme d''une arme double ; elle doit choisir l''une des deux têtes et s''y tenir pour le round.</p>', 1, 0, @res, NULL, @ddver),
  ('Marteau-piolet gnome', @cae_armes_exotiques_deux_mains, 2000, NULL, 3000, NULL, '{"degats_p":"1d6/1d4","degats_m":"1d8/1d6","critique":"×3/×4","portee":"—","type":"Contondant et perforant","part":"Arme double"}', 50, '<p>Le marteau-piolet est une arme double. Il est possible de s''en servir comme si l''on se battait avec deux armes mais, dans ce cas, le personnage encourt les malus habituels du combat à deux armes, comme s''il utilisait une arme à une main et une arme légère. Une créature maniant cette arme à une main ne peut pas s''en servir comme d''une arme double ; elle doit choisir l''une des deux têtes et s''y tenir pour le round.</p>
<p>La tête du marteau est une arme contondante (critique ×3), tandis que le piolet est une arme perforante (critique ×4). L''utilisateur peut choisir la tête de son choix comme arme principale, l''autre est alors l''équivalent de l''arme secondaire.</p>
<p>Cette arme permet de tenter des crocs-en-jambe. Si le personnage échoue dans sa tentative, il peut lâcher son arme pour éviter que le croc-en-jambe ne se retourne contre lui.</p>
<p>Le marteau-piolet est une arme de guerre pour les gnomes et exotique pour toutes les autres races.</p>', 1, 0, @res, NULL, @ddver),
  ('Urgrosh nain', @cae_armes_exotiques_deux_mains, 5000, NULL, 6000, NULL, '{"degats_p":"1d6/1d4","degats_m":"1d8/1d6","critique":"×3","portee":"—","type":"Perforant ou tranchant","part":"Arme double"}', 60, '<p>L''urgrosh nain est une arme double. Il est possible de s''en servir comme si l''on se battait avec deux armes mais, dans ce cas, le personnage encourt les malus habituels du combat à deux armes, comme s''il utilisait une arme à une main et une arme légère. Une créature maniant cette arme à une main ne peut pas s''en servir comme d''une arme double ; elle doit choisir l''une des deux têtes et s''y tenir pour le round. La tête de hache de l''urgrosh est une arme tranchante (critique ×3), tandis que sa pointe est une arme perforante (critique ×3). L''utilisateur peut choisir la tête de son choix comme arme principale ; l''autre est alors l''équivalent de l''arme secondaire.</p>
<p>À condition d''utiliser une action pour préparer une réception de charge, l''urgrosh nain inflige des dégâts doublés à un adversaire qui charge. Quand on utilise un urgrosh pour une réception de charge, c''est la pointe de l''arme qui inflige les dégâts.</p>
<p>L''urgrosh est une arme de guerre pour les nains et exotique pour toutes les autres races.</p>', 1, 0, @res, NULL, @ddver);

-- armes-exotiques-distance
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Arbalète de poing', @cae_armes_exotiques_distance, 10000, NULL, 1000, NULL, '{"degats_p":"1d3","degats_m":"1d4","critique":"19–20/×2","portee":"9 m","type":"Perforant"}', 10, '<p>Une arbalète de poing se tend à la main. Recharger une arbalète de poing est une action de mouvement qui provoque une attaque d''opportunité.</p>
<p>Une arbalète de poing peut être utilisée (mais pas rechargée) d''une seule main sans malus. On peut même utiliser une arbalète de poing dans chaque main, mais avec des malus correspondant au combat à deux armes légères.</p>', 1, 0, @res, NULL, @ddver),
  ('Carreaux d''arbalète de poing (10)', @cae_armes_exotiques_distance, 100, NULL, 500, NULL, '{"degats_p":"—","degats_m":"—","critique":"—","portee":"—","type":"—"}', 20, '<p>Utilisé en tant qu''arme de corps à corps, le carreau est une arme légère improvisée (malus de –4 sur les jets d''attaque) qui inflige autant de dégâts qu''une dague de sa taille (critique ×2). Un carreau atteignant sa cible n''est pas réutilisable. Si le coup est raté, le projectile a 50 % de chances de se casser ou de se perdre.</p>', 1, 0, @res, NULL, @ddver),
  ('Arbalète légère à répétition', @cae_armes_exotiques_distance, 25000, NULL, 3000, NULL, '{"degats_p":"1d6","degats_m":"1d8","critique":"19–20/×2","portee":"24 m","type":"Perforant"}', 30, '<p>Le chargeur de l''arbalète à répétition contient 5 carreaux. Tant que ce chargeur n''est pas vide, on peut recharger l''arbalète simplement en actionnant un levier destiné à cet effet (c''est une action libre). Remplacer un chargeur vide par un plein constitue une action complexe qui provoque une attaque d''opportunité.</p>
<p>Elle peut être utilisée à une main, ou à raison d''une dans chaque main, de la même façon qu''une arbalète ordinaire du même type. Cependant, il faut l''utiliser à deux mains pour actionner le levier ou pour changer de chargeur.</p>', 1, 0, @res, NULL, @ddver),
  ('Arbalète lourde à répétition', @cae_armes_exotiques_distance, 40000, NULL, 6000, NULL, '{"degats_p":"1d8","degats_m":"1d10","critique":"19–20/×2","portee":"36 m","type":"Perforant"}', 40, '<p>Le chargeur de l''arbalète à répétition contient 5 carreaux. Tant que ce chargeur n''est pas vide, on peut recharger l''arbalète simplement en actionnant un levier destiné à cet effet (c''est une action libre). Remplacer un chargeur vide par un plein constitue une action complexe qui provoque une attaque d''opportunité.</p>
<p>Elle peut être utilisée à une main, ou à raison d''une dans chaque main, de la même façon qu''une arbalète ordinaire du même type. Cependant, il faut l''utiliser à deux mains pour actionner le levier ou pour changer de chargeur.</p>', 1, 0, @res, NULL, @ddver),
  ('Carreaux d''arbalète à répétition (5)', @cae_armes_exotiques_distance, 100, NULL, 500, NULL, '{"degats_p":"—","degats_m":"—","critique":"—","portee":"—","type":"—"}', 50, '<p>Les carreaux d''arbalète à répétition sont vendus par 5 dans un carquois de bois. Un carreau atteignant sa cible n''est pas réutilisable. Si le coup est raté, le projectile a 50 % de chances de se casser ou de se perdre.</p>', 1, 0, @res, NULL, @ddver),
  ('Bolas', @cae_armes_exotiques_distance, 500, NULL, 1000, NULL, '{"degats_p":"1d3","degats_m":"1d4","critique":"×2","portee":"3 m","type":"Contondant","part":"Dégâts non létaux"}', 60, '<p>Il est possible de les utiliser pour faire un croc-en-jambe à distance. Même si le personnage échoue dans sa tentative, le croc-en-jambe ne peut se retourner contre lui.</p>', 1, 0, @res, NULL, @ddver),
  ('Filet', @cae_armes_exotiques_distance, 2000, NULL, 3000, NULL, '{"degats_p":"—","degats_m":"—","critique":"—","portee":"3 m","type":"—"}', 70, '<p>Le filet est utilisé pour enchevêtrer l''adversaire. Pour lancer un filet, on effectue un jet d''attaque de contact à distance. La portée maximale du filet est de 3 mètres. En cas de coup au but, la cible est enchevêtrée, ce qui a les effets suivants : malus de –2 aux jets d''attaque, malus de –4 à la Dextérité, vitesse de déplacement réduite de moitié, impossibilité de charger ou de courir. De plus, si le personnage tient solidement la corde, en remportant un test de Force opposé contre sa victime, cette dernière ne peut pas se déplacer en dehors du périmètre imposé par la longueur de la corde. Si elle tente de jeter un sort, il lui faut d''abord réussir un test de Concentration (DD 15).</p>
<p>La victime peut se libérer en réussissant un test d''Évasion (DD 20), ce qui correspond à une action complexe. Le filet a 5 points de résistance et un test de Force réussi permet de le déchirer (DD 25 ; là encore, il s''agit d''une action complexe).</p>
<p>Le filet ne peut immobiliser que des créatures dont la taille est comprise entre les catégories supérieure et inférieure à celle de son utilisateur.</p>
<p>Le filet doit d''abord être replié avant de pouvoir être jeté efficacement. À la première utilisation au cours d''un combat, le jet d''attaque est normal. Par la suite, si le personnage ramène le filet à lui pour le lancer de nouveau, il le fait à –4 au jet d''attaque. Il faut 2 rounds à un personnage formé à son maniement pour replier un filet (sinon 4 rounds).</p>', 1, 0, @res, NULL, @ddver),
  ('Shuriken (5)', @cae_armes_exotiques_distance, 100, NULL, 250, NULL, '{"degats_p":"1","degats_m":"1d2","critique":"×2","portee":"3 m","type":"Perforant"}', 80, '<p>Le shuriken est une arme de moine, ce qui lui permet d''utiliser certains de ses pouvoirs lorsqu''il combat à l''aide de cette arme. Un shuriken ne peut servir au corps à corps.</p>
<p>Bien qu''ils soient des armes de jet, les shurikens sont considérés comme des munitions pour ce qui est de les dégainer, d''en fabriquer des versions de maître ou spéciales et sur les chances de les perdre une fois lancés.</p>', 1, 0, @res, NULL, @ddver);

-- armures-legeres
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Armure matelassée', @cae_armures_legeres, 500, NULL, 5000, NULL, '{"bonus":"+1","dex_max":"+8","malus":"0","echec":"5 %","vit9":"9 m","vit6":"6 m"}', 10, NULL, 1, 0, @res, NULL, @ddver),
  ('Armure de cuir', @cae_armures_legeres, 1000, NULL, 7500, NULL, '{"bonus":"+2","dex_max":"+6","malus":"0","echec":"10 %","vit9":"9 m","vit6":"6 m"}', 20, NULL, 1, 0, @res, NULL, @ddver),
  ('Armure de cuir cloutée', @cae_armures_legeres, 2500, NULL, 10000, NULL, '{"bonus":"+3","dex_max":"+5","malus":"–1","echec":"15 %","vit9":"9 m","vit6":"6 m"}', 30, NULL, 1, 0, @res, NULL, @ddver),
  ('Chemise de mailles', @cae_armures_legeres, 10000, NULL, 12500, NULL, '{"bonus":"+4","dex_max":"+4","malus":"–2","echec":"20 %","vit9":"9 m","vit6":"6 m"}', 40, '<p>Un petit casque en fer est inclus.</p>', 1, 0, @res, NULL, @ddver);

-- armures-intermediaires
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Armure de peau', @cae_armures_intermediaires, 1500, NULL, 12500, NULL, '{"bonus":"+3","dex_max":"+4","malus":"–3","echec":"20 %","vit9":"6 m","vit6":"4,50 m"}', 10, NULL, 1, 0, @res, NULL, @ddver),
  ('Armure d''écailles', @cae_armures_intermediaires, 5000, NULL, 15000, NULL, '{"bonus":"+4","dex_max":"+3","malus":"–4","echec":"25 %","vit9":"6 m","vit6":"4,50 m"}', 20, '<p>Des gantelets sont inclus.</p>', 1, 0, @res, NULL, @ddver),
  ('Cotte de mailles', @cae_armures_intermediaires, 15000, NULL, 20000, NULL, '{"bonus":"+5","dex_max":"+2","malus":"–5","echec":"30 %","vit9":"6 m","vit6":"4,50 m"}', 30, '<p>Des gantelets sont inclus.</p>', 1, 0, @res, NULL, @ddver),
  ('Cuirasse', @cae_armures_intermediaires, 20000, NULL, 15000, NULL, '{"bonus":"+5","dex_max":"+3","malus":"–4","echec":"25 %","vit9":"6 m","vit6":"4,50 m"}', 40, '<p>Elle s''accompagne d''un casque et de jambières.</p>', 1, 0, @res, NULL, @ddver);

-- armures-lourdes
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Clibanion', @cae_armures_lourdes, 20000, NULL, 22500, NULL, '{"bonus":"+6","dex_max":"+0","malus":"–7","echec":"40 %","vit9":"6 m","vit6":"4,50 m"}', 10, '<p>Des gantelets sont inclus.</p>
<p>Quand on court en armure lourde, la vitesse de déplacement est multipliée par trois et non par quatre.</p>', 1, 0, @res, NULL, @ddver),
  ('Crevice', @cae_armures_lourdes, 25000, NULL, 17500, NULL, '{"bonus":"+6","dex_max":"+1","malus":"–6","echec":"35 %","vit9":"6 m","vit6":"4,50 m"}', 20, '<p>Des gantelets sont inclus.</p>
<p>Quand on court en armure lourde, la vitesse de déplacement est multipliée par trois et non par quatre.</p>', 1, 0, @res, NULL, @ddver),
  ('Armure à plaques', @cae_armures_lourdes, 60000, NULL, 25000, NULL, '{"bonus":"+7","dex_max":"+0","malus":"–7","echec":"40 %","vit9":"6 m","vit6":"4,50 m"}', 30, '<p>Des gantelets sont inclus.</p>
<p>Quand on court en armure lourde, la vitesse de déplacement est multipliée par trois et non par quatre.</p>', 1, 0, @res, NULL, @ddver),
  ('Harnois', @cae_armures_lourdes, 150000, NULL, 25000, NULL, '{"bonus":"+8","dex_max":"+1","malus":"–6","echec":"35 %","vit9":"6 m","vit6":"4,50 m"}', 40, '<p>Cette armure inclut des gantelets, des bottes en cuir épais, un heaume (casque à visière) et une épaisse tunique rembourrée sur laquelle elle se porte. Chaque harnois doit être adapté aux mensurations de son porteur par un maître artisan. Il est possible de modifier la taille d''un harnois trouvé ou pris à l''ennemi pour 200–800 po (2d4 × 100).</p>
<p>Quand on court en armure lourde, la vitesse de déplacement est multipliée par trois et non par quatre.</p>', 1, 0, @res, NULL, @ddver);

-- boucliers
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Targe', @cae_boucliers, 1500, NULL, 2500, NULL, '{"bonus":"+1","dex_max":"—","malus":"–1","echec":"5 %","vit9":"—","vit6":"—"}', 10, '<p>Ce petit bouclier en acier se fixe à l''avant-bras, laissant la main libre. On peut donc le porter et tirer à l''arc ou à l''arbalète sans malus. On peut aussi tenir une arme, que ce soit une arme secondaire ou la moitié d''une arme à deux mains, mais le poids supplémentaire au niveau de l''avant-bras impose un malus de –1 sur les jets d''attaque. Ce malus se cumule éventuellement à celui que cause le fait de combattre avec deux armes. Dans tous les cas, un personnage utilisant une arme dans la main de son bras de bouclier ne bénéficie pas du bonus de la targe à la CA.</p>
<p>Il est impossible de donner un coup de bouclier avec une targe.</p>', 1, 0, @res, NULL, @ddver),
  ('Rondache en bois', @cae_boucliers, 300, NULL, 2500, NULL, '{"bonus":"+1","dex_max":"—","malus":"–1","echec":"5 %","vit9":"—","vit6":"—"}', 20, '<p>On fixe le bouclier à son avant-bras et on le maintient en place avec la main. Le poids raisonnable de ce bouclier rond permet de se servir de la main occupée pour tenir autre chose (mais pas pour utiliser une arme).</p>
<p>Qu''elles soient en bois ou en acier, les rondaches confèrent la même protection, mais elles réagissent différemment à certains types d''attaques.</p>
<p><strong>Coup de bouclier.</strong> Il est possible de frapper ses adversaires à coups de rondache, auquel cas elle est utilisée comme une arme secondaire. Les dégâts infligés sont ceux de la rondache de la liste des armes. Utilisée de cette façon, la rondache est considérée comme une arme de guerre contondante, et compte comme une arme légère. Quiconque se sert de sa rondache comme d''une arme perd le bonus qu''elle confère à la CA jusqu''à son prochain tour de jeu. Le bonus d''altération d''une rondache magique ne s''applique pas lors d''un coup de bouclier, mais il est possible de faire d''une rondache une arme magique à part entière.</p>', 1, 0, @res, NULL, @ddver),
  ('Rondache en acier', @cae_boucliers, 900, NULL, 3000, NULL, '{"bonus":"+1","dex_max":"—","malus":"–1","echec":"5 %","vit9":"—","vit6":"—"}', 30, '<p>On fixe le bouclier à son avant-bras et on le maintient en place avec la main. Le poids raisonnable de ce bouclier rond permet de se servir de la main occupée pour tenir autre chose (mais pas pour utiliser une arme).</p>
<p>Qu''elles soient en bois ou en acier, les rondaches confèrent la même protection, mais elles réagissent différemment à certains types d''attaques.</p>
<p><strong>Coup de bouclier.</strong> Il est possible de frapper ses adversaires à coups de rondache, auquel cas elle est utilisée comme une arme secondaire. Les dégâts infligés sont ceux de la rondache de la liste des armes. Utilisée de cette façon, la rondache est considérée comme une arme de guerre contondante, et compte comme une arme légère. Quiconque se sert de sa rondache comme d''une arme perd le bonus qu''elle confère à la CA jusqu''à son prochain tour de jeu. Le bonus d''altération d''une rondache magique ne s''applique pas lors d''un coup de bouclier, mais il est possible de faire d''une rondache une arme magique à part entière.</p>', 1, 0, @res, NULL, @ddver),
  ('Écu en bois', @cae_boucliers, 700, NULL, 5000, NULL, '{"bonus":"+2","dex_max":"—","malus":"–2","echec":"15 %","vit9":"—","vit6":"—"}', 40, '<p>On fixe un écu à son avant-bras et on le maintient en place avec la main. Ce bouclier est trop lourd pour que la main occupée puisse tenir quoi que ce soit.</p>
<p>Qu''ils soient en bois ou en acier, ces boucliers confèrent la même protection, mais ils réagissent différemment à certains types d''attaques.</p>
<p><strong>Coup de bouclier.</strong> Il est possible de frapper ses adversaires à coups d''écu, auquel cas il est utilisé comme une arme secondaire. Les dégâts infligés sont ceux de l''écu de la liste des armes. Utilisé de cette façon, l''écu est considéré comme une arme de guerre contondante, et compte comme une arme à une main. Quiconque se sert de son écu comme d''une arme perd le bonus qu''il confère à la CA jusqu''à son prochain tour de jeu. Le bonus d''altération d''un écu magique ne s''applique pas lors d''un coup de bouclier, mais il est possible de faire d''un écu une arme magique à part entière.</p>', 1, 0, @res, NULL, @ddver),
  ('Écu en acier', @cae_boucliers, 2000, NULL, 7500, NULL, '{"bonus":"+2","dex_max":"—","malus":"–2","echec":"15 %","vit9":"—","vit6":"—"}', 50, '<p>On fixe un écu à son avant-bras et on le maintient en place avec la main. Ce bouclier est trop lourd pour que la main occupée puisse tenir quoi que ce soit.</p>
<p>Qu''ils soient en bois ou en acier, ces boucliers confèrent la même protection, mais ils réagissent différemment à certains types d''attaques.</p>
<p><strong>Coup de bouclier.</strong> Il est possible de frapper ses adversaires à coups d''écu, auquel cas il est utilisé comme une arme secondaire. Les dégâts infligés sont ceux de l''écu de la liste des armes. Utilisé de cette façon, l''écu est considéré comme une arme de guerre contondante, et compte comme une arme à une main. Quiconque se sert de son écu comme d''une arme perd le bonus qu''il confère à la CA jusqu''à son prochain tour de jeu. Le bonus d''altération d''un écu magique ne s''applique pas lors d''un coup de bouclier, mais il est possible de faire d''un écu une arme magique à part entière.</p>', 1, 0, @res, NULL, @ddver),
  ('Pavois', @cae_boucliers, 3000, NULL, 22500, NULL, '{"bonus":"+4","dex_max":"+2","malus":"–10","echec":"50 %","vit9":"—","vit6":"—"}', 60, '<p>Cet énorme bouclier en bois est presque aussi grand que son utilisateur. Dans la plupart des situations, il confère le bonus de bouclier indiqué à la CA. Il peut cependant aussi servir d''abri total, à condition de sacrifier toutes ses attaques. Le pavois ne protège pas contre les sorts ciblés, car le jeteur de sorts n''a qu''à viser le bouclier pour être sûr d''atteindre le personnage. On ne peut pas donner de coups de bouclier avec un pavois et la main qui le tient ne peut être utilisée pour autre chose.</p>
<p>L''utilisation d''un pavois en combat impose un malus de –2 sur les jets d''attaque à cause de l''encombrement du bouclier.</p>', 1, 0, @res, NULL, @ddver);

-- supplements-d-armure
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Pointes pour armure', @cae_supplements_d_armure, NULL, '+50 po', NULL, '+5 kg', '{"bonus":"—","dex_max":"—","malus":"—","echec":"—","vit9":"—","vit6":"—"}', 10, '<p>Il est possible d''ajouter des pointes à son armure, grâce auxquelles on peut infliger des dégâts perforants supplémentaires (voir l''<em>armure à pointes</em> dans la liste des armes) sur un test de lutte réussi lorsque l''on agrippe un adversaire. Les pointes sont considérées comme des armes de guerre. Si le personnage n''est pas formé à leur maniement, il subit un malus de –4 à son test de lutte. Il est également possible de se servir des pointes pour délivrer une attaque normale (ou secondaire), auquel cas elles comptent comme des armes légères. (Il est impossible de porter deux attaques secondaires lors du même round, même si elles proviennent de sources distinctes, comme une armure à pointes et une dague dans la main non directrice.)</p>
<p>Le bonus d''altération d''une armure n''augmente en rien l''efficacité des pointes, mais on peut en faire une arme magique séparée.</p>', 1, 0, @res, NULL, @ddver),
  ('Gantelet d''armes', @cae_supplements_d_armure, 800, NULL, NULL, '+2,5 kg', '{"bonus":"—","dex_max":"—","malus":"Spécial","echec":"—","vit9":"—","vit6":"—"}', 20, '<p>Ce gantelet métallique est équipé de courtes chaînes et de lanières permettant à l''utilisateur d''accrocher son arme, de manière à bien la garder en main. Ce système confère un bonus de +10 aux jets pour résister au désarmement. Attacher son arme (ou, au contraire, la détacher) constitue une action complexe donnant lieu à une attaque d''opportunité. Le prix indiqué s''entend pour un gantelet seulement et le poids mentionné ne s''applique que si le personnage porte une cuirasse, une armure légère ou pas d''armure du tout. Sinon, le gantelet d''armes remplace tout simplement un des gantelets intégrés à l''armure (compris dans le poids).</p>
<p>Tant que les fixations du gantelet sont attachées, la main qui se trouve à l''intérieur ne peut plus servir à jeter des sorts à composante gestuelle ou à utiliser des compétences (le personnage peut tout de même lancer des sorts à composante gestuelle si son autre main reste libre).</p>
<p>Tout comme les autres gantelets, le gantelet d''armes permet d''infliger des dégâts létaux (au lieu de dégâts non-létaux) quand on se bat à coups de poings.</p>', 1, 0, @res, NULL, @ddver),
  ('Pointes pour bouclier', @cae_supplements_d_armure, NULL, '+10 po', NULL, '+2,5 kg', '{"bonus":"—","dex_max":"—","malus":"—","echec":"—","vit9":"—","vit6":"—"}', 30, '<p>Quand on les ajoute à une rondache ou un écu, ces pointes le transforment en arme de guerre perforante et augmentent les dégâts infligés par un coup de bouclier (voir la liste des armes). On ne peut pas garnir une targe ou un pavois de pointes. Les dégâts (et leur type) exceptés, les coups de bouclier s''exécutent comme indiqué pour une rondache ou un écu. Le bonus d''altération d''un écu ou d''une rondache magique n''augmente en rien l''efficacité des pointes, mais on peut en faire une arme magique séparée.</p>', 1, 0, @res, NULL, @ddver);

-- materiel-d-aventurier
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Aiguille à coudre', @cae_materiel_d_aventurier, 50, NULL, NULL, NULL, NULL, 10, NULL, 1, 0, @res, NULL, @ddver),
  ('Bélier portable', @cae_materiel_d_aventurier, 1000, NULL, 10000, NULL, NULL, 20, '<p>Le bélier portable confère un bonus de circonstances de +2 au jet de Force pour enfoncer une porte, et permet au personnage de se faire aider d''un compagnon, ce qui peut augmenter le bonus de +2.</p>', 1, 0, @res, NULL, @ddver),
  ('Bois de chauffage (pour un jour)', @cae_materiel_d_aventurier, 1, NULL, 10000, NULL, NULL, 30, NULL, 1, 0, @res, NULL, @ddver),
  ('Bougie', @cae_materiel_d_aventurier, 1, NULL, NULL, NULL, NULL, 40, '<p>Une bougie éclaire une zone de 1,50 mètre de rayon et brûle pendant 1 heure.</p>', 1, 0, @res, NULL, @ddver),
  ('Bouteille de vin en verre', @cae_materiel_d_aventurier, 200, NULL, NULL, NULL, NULL, 50, NULL, 1, 0, @res, NULL, @ddver),
  ('Cadenas très simple', @cae_materiel_d_aventurier, 2000, NULL, 500, NULL, NULL, 60, '<p>Le degré de difficulté (DD) nécessaire pour forcer un cadenas à l''aide de la compétence Crochetage dépend de sa qualité : très simple (DD 20), moyen (DD 25), bon (DD 30) ou excellent (DD 40).</p>', 1, 0, @res, NULL, @ddver),
  ('Cadenas moyen', @cae_materiel_d_aventurier, 4000, NULL, 500, NULL, NULL, 70, '<p>Le degré de difficulté (DD) nécessaire pour forcer un cadenas à l''aide de la compétence Crochetage dépend de sa qualité : très simple (DD 20), moyen (DD 25), bon (DD 30) ou excellent (DD 40).</p>', 1, 0, @res, NULL, @ddver),
  ('Cadenas bon', @cae_materiel_d_aventurier, 8000, NULL, 500, NULL, NULL, 80, '<p>Le degré de difficulté (DD) nécessaire pour forcer un cadenas à l''aide de la compétence Crochetage dépend de sa qualité : très simple (DD 20), moyen (DD 25), bon (DD 30) ou excellent (DD 40).</p>', 1, 0, @res, NULL, @ddver),
  ('Cadenas excellent', @cae_materiel_d_aventurier, 15000, NULL, 500, NULL, NULL, 90, '<p>Le degré de difficulté (DD) nécessaire pour forcer un cadenas à l''aide de la compétence Crochetage dépend de sa qualité : très simple (DD 20), moyen (DD 25), bon (DD 30) ou excellent (DD 40).</p>', 1, 0, @res, NULL, @ddver),
  ('Chaîne, 3 m', @cae_materiel_d_aventurier, 3000, NULL, 1000, NULL, NULL, 100, '<p>Une chaîne a une valeur de solidité de 10 et 5 points de résistance. On peut la casser en réussissant un test de Force (DD 26).</p>', 1, 0, @res, NULL, @ddver),
  ('Chausse-trappes', @cae_materiel_d_aventurier, 100, NULL, 1000, NULL, NULL, 110, '<p>Les chausse-trappes sont de petites billes métalliques dotées de quatre pointes équidistantes, de telle manière qu''il y en a toujours une dirigée vers le haut. On les éparpille sur le sol, dans l''espoir que l''adversaire marchera dessus, ou du moins qu''il sera forcé de ralentir pour les éviter. Une bourse de chausse-trappes couvre un carré de 1,50 mètre de côté.</p>
<p>Chaque fois qu''une créature entre dans une zone couverte de chausse-trappes (ou passe un round à combattre en un tel endroit), elle court le risque de marcher sur l''une des pointes. Le jet d''attaque des chausse-trappes (bonus de base à l''attaque +0) ne prend en compte ni le bonus d''armure, ni le bonus de bouclier, ni le bonus de parade de la créature (ce dernier permet de détourner les attaques, mais il n''empêche pas de toucher quelque chose de dangereux). Si la créature porte des chaussures, des bottes ou autre, elle bénéficie d''un bonus de +2 à sa CA. Si les chausse-trappes « touchent », la créature a marché sur l''une d''elles. La pointe lui inflige 1 point de dégâts et cette plaie à la plante du pied réduit par la suite de moitié sa vitesse de déplacement. Cette pénalité se prolonge un jour durant, à moins que le blessé ne soit soigné par la compétence Premiers secours (DD 15) ou ne soit guéri d''au moins 1 point par magie. Une créature en train de courir ou de charger doit immédiatement s''arrêter si elle marche sur une chausse-trappe. Par contre, si elle ralentit suffisamment sa vitesse de déplacement (à la moitié de sa valeur normale), elle peut négocier la zone piégée sans encombre.</p>', 1, 0, @res, NULL, @ddver),
  ('Chevalière', @cae_materiel_d_aventurier, 500, NULL, NULL, NULL, NULL, 120, NULL, 1, 0, @res, NULL, @ddver),
  ('Chope en terre cuite', @cae_materiel_d_aventurier, 2, NULL, 500, NULL, NULL, 130, NULL, 1, 0, @res, NULL, @ddver),
  ('Cire à cacheter', @cae_materiel_d_aventurier, 100, NULL, 500, NULL, NULL, 140, NULL, 1, 0, @res, NULL, @ddver),
  ('Cloche', @cae_materiel_d_aventurier, 100, NULL, NULL, NULL, NULL, 150, NULL, 1, 0, @res, NULL, @ddver),
  ('Coffre, vide', @cae_materiel_d_aventurier, 200, NULL, 12500, NULL, NULL, 160, NULL, 1, 0, @res, NULL, @ddver),
  ('Corde en chanvre, 15 m', @cae_materiel_d_aventurier, 100, NULL, 5000, NULL, NULL, 170, '<p>Cette corde a 2 points de résistance. Un test de Force réussi (DD 23) permet de la rompre.</p>', 1, 0, @res, NULL, @ddver),
  ('Corde en soie, 15 m', @cae_materiel_d_aventurier, 1000, NULL, 2500, NULL, NULL, 180, '<p>Cette corde a 4 points de résistance et le test de Force nécessaire pour la rompre est plus difficile à réussir (DD 24). Elle confère un bonus de +2 aux tests de Maîtrise des cordes.</p>', 1, 0, @res, NULL, @ddver),
  ('Couverture d''hiver', @cae_materiel_d_aventurier, 50, NULL, 1500, NULL, NULL, 190, NULL, 1, 0, @res, NULL, @ddver),
  ('Craie, morceau', @cae_materiel_d_aventurier, 1, NULL, NULL, NULL, NULL, 200, NULL, 1, 0, @res, NULL, @ddver),
  ('Cruche en terre cuite', @cae_materiel_d_aventurier, 2, NULL, 2500, NULL, NULL, 210, NULL, 1, 0, @res, NULL, @ddver),
  ('Échelle, 3 m', @cae_materiel_d_aventurier, 5, NULL, 10000, NULL, NULL, 220, '<p>Une échelle droite toute simple.</p>', 1, 0, @res, NULL, @ddver),
  ('Encre, la fiole', @cae_materiel_d_aventurier, 800, NULL, NULL, NULL, NULL, 230, '<p>Il s''agit d''encre noire. On peut en obtenir d''autres couleurs, mais le prix est alors doublé.</p>', 1, 0, @res, NULL, @ddver),
  ('Étui à carte ou à parchemin', @cae_materiel_d_aventurier, 100, NULL, 250, NULL, NULL, 240, NULL, 1, 0, @res, NULL, @ddver),
  ('Filet de pêche, 2,5 m²', @cae_materiel_d_aventurier, 400, NULL, 2500, NULL, NULL, 250, NULL, 1, 0, @res, NULL, @ddver),
  ('Fiole pour encre ou potion', @cae_materiel_d_aventurier, 100, NULL, 50, NULL, NULL, 260, '<p>Elle ne fait pas plus de 7 ou 8 centimètres de long pour 2 ou 3 de large. Elle contient environ 30 centilitres de liquide.</p>', 1, 0, @res, NULL, @ddver),
  ('Flasque (vide)', @cae_materiel_d_aventurier, 3, NULL, 2250, NULL, NULL, 270, '<p>Ce récipient en céramique, verre ou métal est vendu avec un bouchon. Il contient un demi-litre de liquide.</p>', 1, 0, @res, NULL, @ddver),
  ('Grappin', @cae_materiel_d_aventurier, 100, NULL, 2000, NULL, NULL, 280, '<p>Lancer un grappin avec succès nécessite un test de Maîtrise des cordes (DD 10 +2 par 3 mètres de distance à parcourir).</p>', 1, 0, @res, NULL, @ddver),
  ('Hameçon', @cae_materiel_d_aventurier, 10, NULL, NULL, NULL, NULL, 290, NULL, 1, 0, @res, NULL, @ddver),
  ('Huile, la flasque', @cae_materiel_d_aventurier, 10, NULL, 500, NULL, NULL, 300, '<p>L''huile végétale brûle au rythme d''un demi-litre toutes les 6 heures dans une lanterne. Une flasque d''huile peut être utilisée comme projectile à impact. Référez-vous aux règles concernant le feu grégeois, sauf qu''une action complexe est nécessaire pour préparer une flasque en lui ajoutant une mèche. Une fois le projectile jeté, l''huile n''a que 50 % de chances de s''enflammer au moment de l''impact.</p>
<p>Une flasque renversée sur le sol couvre une surface de 1,50 mètre de côté (à condition que le revêtement soit lisse). Si on allume l''huile, elle brûle pendant 2 rounds et inflige 1d3 points de dégâts à toute créature comprise dans la zone dangereuse.</p>', 1, 0, @res, NULL, @ddver),
  ('Jarre en terre cuite', @cae_materiel_d_aventurier, 3, NULL, 4500, NULL, NULL, 310, '<p>Cette jarre en terre cuite est vendue avec un bouchon. Elle peut contenir 4 litres de liquide.</p>', 1, 0, @res, NULL, @ddver),
  ('Lampe', @cae_materiel_d_aventurier, 10, NULL, 500, NULL, NULL, 320, '<p>Une lampe éclaire vivement une zone de 4,50 mètres de rayon et éclaire faiblement une zone de 9 mètres de rayon. Elle brûle le contenu de son réservoir d''un demi-litre en 6 heures. On peut la tenir dans une main.</p>', 1, 0, @res, NULL, @ddver),
  ('Lanterne à capote', @cae_materiel_d_aventurier, 700, NULL, 1000, NULL, NULL, 330, '<p>Elle éclaire vivement une zone de 9 mètres de rayon et éclaire faiblement une zone de 18 mètres de rayon. Elle brûle l''huile de son réservoir (un demi-litre) en 6 heures. On peut la tenir d''une main.</p>', 1, 0, @res, NULL, @ddver),
  ('Lanterne sourde', @cae_materiel_d_aventurier, 1200, NULL, 1500, NULL, NULL, 340, '<p>Elle éclaire vivement un cône de 18 mètres de long et éclaire faiblement dans un cône de 36 mètres de long. Elle brûle l''intégralité de son réservoir d''un demi-litre en 6 heures. On peut la tenir d''une main.</p>', 1, 0, @res, NULL, @ddver),
  ('Longue-vue', @cae_materiel_d_aventurier, 100000, NULL, 500, NULL, NULL, 350, '<p>La longue-vue a un pouvoir grossissant de deux fois.</p>', 1, 0, @res, NULL, @ddver),
  ('Marteau', @cae_materiel_d_aventurier, 50, NULL, 1000, NULL, NULL, 360, '<p>On peut l''utiliser en combat, comme une arme à une main improvisée qui inflige des dégâts contondants égaux à ceux d''un gantelet clouté de sa taille.</p>', 1, 0, @res, NULL, @ddver),
  ('Masse', @cae_materiel_d_aventurier, 100, NULL, 5000, NULL, NULL, 370, NULL, 1, 0, @res, NULL, @ddver),
  ('Menottes', @cae_materiel_d_aventurier, 1500, NULL, 1000, NULL, NULL, 380, '<p>Les menottes permettent d''entraver une créature de taille M. Le prisonnier peut se libérer à l''aide de la compétence Évasion (DD 30, ou DD 35 dans le cas de menottes de qualité supérieure). Briser les menottes est possible, en réussissant un test de Force (DD 26, ou DD 28 pour des menottes de qualité supérieure). Une paire de menottes a une valeur de solidité de 10 et 10 points de résistance. La plupart s''accompagnent d''un cadenas ; dans ce cas, il faut ajouter le coût de ce dernier pour obtenir le prix total des menottes.</p><p>Pour la même somme, il est possible d''acheter des menottes pour créatures de taille P. Pour créatures de taille G, elles valent dix fois plus cher, et cent fois plus cher pour les monstres de taille TG. Les créatures de taille C, Gig, TP, Min ou I ne peuvent être entravées que par des menottes faites sur mesure.</p>', 1, 0, @res, NULL, @ddver),
  ('Menottes de qualité supérieure', @cae_materiel_d_aventurier, 5000, NULL, 1000, NULL, NULL, 390, '<p>Les menottes permettent d''entraver une créature de taille M. Le prisonnier peut se libérer à l''aide de la compétence Évasion (DD 30, ou DD 35 dans le cas de menottes de qualité supérieure). Briser les menottes est possible, en réussissant un test de Force (DD 26, ou DD 28 pour des menottes de qualité supérieure). Une paire de menottes a une valeur de solidité de 10 et 10 points de résistance. La plupart s''accompagnent d''un cadenas ; dans ce cas, il faut ajouter le coût de ce dernier pour obtenir le prix total des menottes.</p><p>Pour la même somme, il est possible d''acheter des menottes pour créatures de taille P. Pour créatures de taille G, elles valent dix fois plus cher, et cent fois plus cher pour les monstres de taille TG. Les créatures de taille C, Gig, TP, Min ou I ne peuvent être entravées que par des menottes faites sur mesure.</p>', 1, 0, @res, NULL, @ddver),
  ('Outre', @cae_materiel_d_aventurier, 100, NULL, 2000, NULL, NULL, 400, NULL, 1, 0, @res, NULL, @ddver),
  ('Paillasse', @cae_materiel_d_aventurier, 10, NULL, 2500, NULL, NULL, 410, NULL, 1, 0, @res, NULL, @ddver),
  ('Palan', @cae_materiel_d_aventurier, 500, NULL, 2500, NULL, NULL, 420, NULL, 1, 0, @res, NULL, @ddver),
  ('Panier (vide)', @cae_materiel_d_aventurier, 40, NULL, 500, NULL, NULL, 430, NULL, 1, 0, @res, NULL, @ddver),
  ('Papier, la feuille', @cae_materiel_d_aventurier, 40, NULL, NULL, NULL, NULL, 440, NULL, 1, 0, @res, NULL, @ddver),
  ('Parchemin, la feuille', @cae_materiel_d_aventurier, 20, NULL, NULL, NULL, NULL, 450, NULL, 1, 0, @res, NULL, @ddver),
  ('Pelle', @cae_materiel_d_aventurier, 200, NULL, 4000, NULL, NULL, 460, NULL, 1, 0, @res, NULL, @ddver),
  ('Perche, 3 m', @cae_materiel_d_aventurier, 20, NULL, 4000, NULL, NULL, 470, NULL, 1, 0, @res, NULL, @ddver),
  ('Petit miroir en acier', @cae_materiel_d_aventurier, 1000, NULL, 250, NULL, NULL, 480, NULL, 1, 0, @res, NULL, @ddver),
  ('Pied-de-biche', @cae_materiel_d_aventurier, 200, NULL, 2500, NULL, NULL, 490, '<p>Un pied-de-biche est l''outil idéal pour ouvrir les portes et les coffres, briser les chaînes et ainsi de suite. Il confère un bonus de circonstances de +2 sur les tests de Force afférents à ces activités. On peut l''utiliser en combat, comme une arme à une main improvisée qui inflige des dégâts contondants égaux à ceux d''un gourdin de sa taille.</p>', 1, 0, @res, NULL, @ddver),
  ('Pierre à aiguiser', @cae_materiel_d_aventurier, 2, NULL, 500, NULL, NULL, 500, NULL, 1, 0, @res, NULL, @ddver),
  ('Pioche de mineur', @cae_materiel_d_aventurier, 300, NULL, 5000, NULL, NULL, 510, NULL, 1, 0, @res, NULL, @ddver),
  ('Piton', @cae_materiel_d_aventurier, 10, NULL, 250, NULL, NULL, 520, NULL, 1, 0, @res, NULL, @ddver),
  ('Plume d''écriture', @cae_materiel_d_aventurier, 10, NULL, NULL, NULL, NULL, 530, '<p>Ce bâtonnet en bois est pourvu d''une extrémité spéciale, qui aspire l''encre quand on le trempe dans une fiole, et qui permet ensuite d''écrire quand on en frotte la pointe sur une surface plane.</p>', 1, 0, @res, NULL, @ddver),
  ('Pot en fer', @cae_materiel_d_aventurier, 50, NULL, 5000, NULL, NULL, 540, NULL, 1, 0, @res, NULL, @ddver),
  ('Rations de survie (par jour)', @cae_materiel_d_aventurier, 50, NULL, 500, NULL, NULL, 550, NULL, 1, 0, @res, NULL, @ddver),
  ('Sac (vide)', @cae_materiel_d_aventurier, 10, NULL, 250, NULL, NULL, 560, NULL, 1, 0, @res, NULL, @ddver),
  ('Sac à dos (vide)', @cae_materiel_d_aventurier, 200, NULL, 1000, NULL, NULL, 570, NULL, 1, 0, @res, NULL, @ddver),
  ('Sacoche de ceinture', @cae_materiel_d_aventurier, 100, NULL, 500, NULL, NULL, 580, NULL, 1, 0, @res, NULL, @ddver),
  ('Savon, 1 livre', @cae_materiel_d_aventurier, 50, NULL, 500, NULL, NULL, 590, NULL, 1, 0, @res, NULL, @ddver),
  ('Seau (vide)', @cae_materiel_d_aventurier, 50, NULL, 1000, NULL, NULL, 600, NULL, 1, 0, @res, NULL, @ddver),
  ('Sifflet', @cae_materiel_d_aventurier, 80, NULL, NULL, NULL, NULL, 610, NULL, 1, 0, @res, NULL, @ddver),
  ('Silex et amorce', @cae_materiel_d_aventurier, 100, NULL, NULL, NULL, NULL, 620, '<p>Il faut une action complexe pour allumer une torche de la sorte, et vraisemblablement plus pour faire démarrer un autre feu.</p>', 1, 0, @res, NULL, @ddver),
  ('Tente', @cae_materiel_d_aventurier, 1000, NULL, 10000, NULL, NULL, 630, NULL, 1, 0, @res, NULL, @ddver),
  ('Toile (le m²)', @cae_materiel_d_aventurier, 10, NULL, 1000, NULL, NULL, 640, NULL, 1, 0, @res, NULL, @ddver),
  ('Tonneau (vide)', @cae_materiel_d_aventurier, 200, NULL, 15000, NULL, NULL, 650, NULL, 1, 0, @res, NULL, @ddver),
  ('Torche', @cae_materiel_d_aventurier, 1, NULL, 500, NULL, NULL, 660, '<p>Une torche éclaire vivement une zone de 6 mètres de rayon et éclaire faiblement une zone de 12 mètres de rayon. Elle brûle pendant 1 heure. On peut l''utiliser en combat, comme une arme à une main improvisée qui inflige des dégâts contondants égaux à ceux d''un gantelet de sa taille.</p>', 1, 0, @res, NULL, @ddver);

-- substances-et-objets-speciaux
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Acide (flasque)', @cae_substances_et_objets_speciaux, 1000, NULL, 500, NULL, NULL, 10, '<p>On peut lancer une flasque d''acide comme une arme à impact. Le personnage doit effectuer une attaque de contact à distance avec un facteur de portée de 3 mètres. Un coup au but inflige 1d6 points de dégâts d''acide. L''aspersion inflige 1 point de dégâts d''acide à toutes les créatures situées à 1,50 mètre du point d''impact.</p>', 1, 0, @res, NULL, @ddver),
  ('Allume-feu', @cae_substances_et_objets_speciaux, 100, NULL, NULL, NULL, NULL, 20, '<p>La substance alchimique collée à l''extrémité de ce minuscule bâtonnet en bois s''allume quand on le frotte contre une surface dure. Un allume-feu permet d''obtenir une flamme bien plus rapidement qu''une loupe ou un silex et une amorce. Allumer une torche de la sorte constitue une action simple (plutôt que complexe). Allumer n''importe quel autre type de feu exige au moins une action simple.</p>', 1, 0, @res, NULL, @ddver),
  ('Antidote (fiole)', @cae_substances_et_objets_speciaux, 5000, NULL, NULL, NULL, NULL, 30, '<p>Le fait d''ingérer un antidote confère un bonus d''alchimie de +5 aux jets de Vigueur contre le poison pendant 1 heure.</p>', 1, 0, @res, NULL, @ddver),
  ('Bâton éclairant', @cae_substances_et_objets_speciaux, 200, NULL, 500, NULL, NULL, 40, '<p>Ce bâtonnet en fer long de 30 centimètres et à l''extrémité dorée dégage une vive lumière quand on le tape. Il éclaire vivement une zone de 9 mètres de rayon et éclaire faiblement une zone de 18 mètres de rayon. Il brûle pendant 6 heures, après quoi son bout en or se consume et devient inutilisable.</p>', 1, 0, @res, NULL, @ddver),
  ('Bâton fumigène', @cae_substances_et_objets_speciaux, 2000, NULL, 250, NULL, NULL, 50, '<p>Ce bâtonnet en bois traité à l''aide d''un produit chimique libère une épaisse fumée opaque quand on y met le feu. La brume remplit un cube de 3 mètres d''arête (les effets sont par ailleurs similaires à ceux du sort <em>nappe de brouillard</em>). Le bâton est dévoré par les flammes en 1 round et la fumée se dissipe ensuite naturellement.</p>', 1, 0, @res, NULL, @ddver),
  ('Eau bénite (flasque)', @cae_substances_et_objets_speciaux, 2500, NULL, 500, NULL, NULL, 60, '<p>L''eau bénite brûle les morts-vivants et les Extérieurs d''alignement mauvais comme si ces derniers recevaient de l''acide. On peut lancer une flasque d''eau bénite comme une arme à impact. Le personnage doit effectuer une attaque de contact à distance avec un facteur de portée de 3 mètres. La flasque se brise au contact d''une créature corporelle, mais pour l''utiliser contre une créature incorporelle, il faut ouvrir le récipient et verser l''eau bénite sur la cible. Cela n''est possible que si la créature incorporelle est adjacente au personnage. Cela constitue par ailleurs une attaque de contact à distance qui ne provoque pas d''attaque d''opportunité.</p>
<p>Un coup au but inflige 2d4 points de dégâts à un mort-vivant ou un Extérieur mauvais. L''aspersion inflige 1 point de dégâts d''acide à toutes les créatures de ce type situées à 1,50 mètre du point d''impact.</p>
<p>Les temples consacrés aux dieux bons vendent l''eau bénite à prix coûtant. Elle ne peut pas être fabriquée à l''aide de la compétence Artisanat (alchimie).</p>', 1, 0, @res, NULL, @ddver),
  ('Feu grégeois (flasque)', @cae_substances_et_objets_speciaux, 2000, NULL, 500, NULL, NULL, 70, '<p>On peut lancer une flasque de feu grégeois comme une arme à impact. Le personnage doit effectuer une attaque de contact à distance avec un facteur de portée de 3 mètres. Un coup au but inflige 1d6 points de dégâts de feu. L''aspersion inflige 1 point de dégâts de feu à toutes les créatures situées à 1,50 mètre du point d''impact. Le round suivant, la victime d''un coup au but subit de nouveau 1d6 points de dégâts de feu. Elle peut avant cela tenter d''étouffer les flammes, ce qui constitue une action complexe et demande un jet de Réflexes (DD 15). Rouler sur le sol donne un bonus de +2 à ce jet. S''immerger dans l''eau ou étouffer les flammes magiquement a automatiquement le même effet.</p>', 1, 0, @res, NULL, @ddver),
  ('Pierre à tonnerre', @cae_substances_et_objets_speciaux, 3000, NULL, 500, NULL, NULL, 80, '<p>On peut lancer cette arme comme une arme à impact. Le personnage doit effectuer une attaque de contact à distance avec un facteur de portée de 6 mètres. Dès qu''elle touche une surface dure (ou quand on la tape assez fort), elle produit un bruit terrible, considéré comme une attaque de son. Toutes les créatures se trouvant à moins de 3 mètres de distance doivent réussir un jet de Vigueur (DD 15) sous peine de devenir sourdes pendant 1 heure. En plus des effets manifestes, les individus sourds subissent un malus de –4 à l''initiative et 20 % de chances de rater l''incantation de tout sort à composante vocale qu''ils pourraient vouloir jeter (auquel cas le sort est perdu).</p>
<p>Puisque le personnage ne cible pas une créature en particulier, il vise simplement une case de 1,50 mètre de côté. On considère qu''une case a une CA de 5. Si l''attaque échoue, la pierre tombe ailleurs.</p>', 1, 0, @res, NULL, @ddver),
  ('Sacoche immobilisante', @cae_substances_et_objets_speciaux, 5000, NULL, 2000, NULL, NULL, 90, '<p>Cette sacoche sphérique est pleine d''une substance gluante obtenue par alchimie. Elle se lance comme une arme à impact. Le personnage doit effectuer une attaque de contact à distance avec un facteur de portée de 3 mètres. En cas de coup au but, le tissu se déchire et la colle recouvre la victime, durcissant immédiatement au contact de l''air. La créature enchevêtrée subit un malus de –2 aux jets d''attaque et un autre de –4 à sa Dextérité effective. Si elle rate un jet de Réflexes (DD 15), elle est également collée au sol et incapable de bouger. Même en cas de succès, sa vitesse de déplacement est réduite de moitié. Une créature de taille TG ou plus grande n''est pas affectée par une sacoche immobilisante. Une créature volante n''est pas collée au sol, mais doit réussir un jet de Réflexes de DD 15 pour continuer à voler (à condition qu''elle doive battre des ailes pour voler), sous peine de chuter immédiatement. Une sacoche immobilisante ne fonctionne pas sous l''eau.</p>
<p>Une créature collée au sol (ou incapable de voler) peut se libérer en réussissant un test de Force (DD 17) ou en infligeant 15 points de dégâts à la glu à l''aide d''une arme tranchante. Il n''a pas besoin de jouer de jet d''attaque (pas plus qu''un compagnon l''assistant) : il touche automatiquement, et il faut préciser la quantité de colle qu''il ôte à chaque fois en déterminant les dégâts. Une fois libéré, le personnage peut se déplacer à vitesse réduite de moitié. Un jeteur de sorts immobilisé par la glu doit réussir un test de Concentration (DD 15) chaque fois qu''il désire faire appel à sa magie. La colle devient friable au bout de 2d4 rounds, s''effrite et perd toute efficacité. Une application du solvant universel dissout la colle instantanément et libère la créature.</p>', 1, 0, @res, NULL, @ddver),
  ('Torche éternelle', @cae_substances_et_objets_speciaux, 11000, NULL, 500, NULL, NULL, 100, '<p>Cette torche d''apparence ordinaire a reçu un sort de <em>flamme éternelle</em>. Une torche éternelle éclaire vivement une zone de 6 mètres de rayon et éclaire faiblement une zone de 12 mètres de rayon. Elle ne peut pas être fabriquée à l''aide de la compétence Artisanat (alchimie).</p>', 1, 0, @res, NULL, @ddver);

-- materiel-de-classe-et-de-competence
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Balance', @cae_materiel_de_classe_et_de_competence, 200, NULL, 500, NULL, NULL, 10, '<p>Cette balance confère un bonus de circonstances de +2 aux tests d''Évaluation si l''on s''en sert pour déterminer la valeur d''objets ou de substances se vendant au poids, comme c''est le cas pour les métaux précieux.</p>', 1, 0, @res, NULL, @ddver),
  ('Clepsydre', @cae_materiel_de_classe_et_de_competence, 100000, NULL, 100000, NULL, NULL, 20, '<p>Cette horloge imposante est précise à une demi-heure près par jour. Elle a besoin d''une source d''eau continue et régulée, car c''est la vitesse à laquelle les gouttes s''écoulent qui lui permet de calculer le temps.</p>', 1, 0, @res, NULL, @ddver),
  ('Houx et gui', @cae_materiel_de_classe_et_de_competence, NULL, NULL, NULL, NULL, NULL, 30, NULL, 1, 0, @res, NULL, @ddver),
  ('Instrument de musique courant', @cae_materiel_de_classe_et_de_competence, 500, NULL, 1500, NULL, NULL, 40, NULL, 1, 0, @res, NULL, @ddver),
  ('Instrument de musique de maître', @cae_materiel_de_classe_et_de_competence, 10000, NULL, 1500, NULL, NULL, 50, '<p>Les instruments de maître confèrent un bonus de circonstances de +2 aux tests de Représentation.</p>', 1, 0, @res, NULL, @ddver),
  ('Grimoire (vierge)', @cae_materiel_de_classe_et_de_competence, 1500, NULL, 1500, NULL, NULL, 60, '<p>Le livre contient 100 pages de parchemin, chaque sort prenant 1 page par niveau (une page pour un sort de niveau 0).</p>', 1, 0, @res, NULL, @ddver),
  ('Laboratoire d''alchimie', @cae_materiel_de_classe_et_de_competence, 50000, NULL, 20000, NULL, NULL, 70, '<p>Étudié pour, il confère un bonus de circonstances de +2 aux tests d''Artisanat (alchimie), sans pour autant réduire les coûts de fabrication d''un objet (voir Artisanat (alchimie)). Sans ce laboratoire, on considère que le personnage maîtrisant cette compétence possède le strict minimum en matière d''ustensiles, ce qui ne lui permet pas de bénéficier du bonus de +2 au test de compétence.</p>', 1, 0, @res, NULL, @ddver),
  ('Loupe', @cae_materiel_de_classe_et_de_competence, 10000, NULL, NULL, NULL, NULL, 80, '<p>Cette lentille de verre permet de voir les objets de près. Elle permet également d''allumer un feu quand on n''a pas de silex et d''amorce (mais il faut pour cela bénéficier d''un grand soleil, et d''une action complexe pour réussir à allumer quelques brindilles). Elle confère un bonus de circonstances de +2 aux tests d''Évaluation lorsqu''on s''intéresse aux objets de petite taille ou extrêmement détaillés, tels que les pierres précieuses.</p>', 1, 0, @res, NULL, @ddver),
  ('Matériel d''escalade', @cae_materiel_de_classe_et_de_competence, 8000, NULL, 2500, NULL, NULL, 90, '<p>Ces outils idéaux confèrent un bonus de circonstances de +2 aux tests d''Escalade.</p>', 1, 0, @res, NULL, @ddver),
  ('Outils d''artisan', @cae_materiel_de_classe_et_de_competence, 500, NULL, 2500, NULL, NULL, 100, '<p>Ces outils sont conçus pour un type d''artisanat bien précis (à déterminer). Sans eux, le personnage doit utiliser des outils improvisés, ce qui lui impose un malus de circonstances de –2 à ses tests d''Artisanat (ou l''empêche purement et simplement de se servir de sa compétence).</p>', 1, 0, @res, NULL, @ddver),
  ('Outils de maître artisan', @cae_materiel_de_classe_et_de_competence, 5500, NULL, 2500, NULL, NULL, 110, '<p>Similaires aux outils d''artisan, si ce n''est qu''ils s''adaptent tellement à l''artisanat concerné qu''ils confèrent un bonus de circonstances de +2 aux tests de compétence.</p>', 1, 0, @res, NULL, @ddver),
  ('Outils de cambrioleur', @cae_materiel_de_classe_et_de_competence, 3000, NULL, 500, NULL, NULL, 120, '<p>Ces outils sont indispensables pour utiliser les compétences Crochetage et Désamorçage/sabotage. Sans ces outils, il faut improviser, ce qui impose un malus de circonstances de –2 aux tests de Crochetage et de Désamorçage/sabotage.</p>', 1, 0, @res, NULL, @ddver),
  ('Outils de cambrioleur de qualité supérieure', @cae_materiel_de_classe_et_de_competence, 10000, NULL, 1000, NULL, NULL, 130, '<p>Cette trousse contient des outils supplémentaires par rapport à la précédente et la qualité de l''ensemble est nettement meilleure, ce qui confère un bonus de circonstances de +2 aux tests de Crochetage et de Désamorçage/sabotage.</p>', 1, 0, @res, NULL, @ddver),
  ('Outil de qualité supérieure', @cae_materiel_de_classe_et_de_competence, 5000, NULL, 500, NULL, NULL, 140, '<p>Cet objet de qualité exceptionnelle confère un bonus de circonstances de +2 au test de compétence correspondant (le cas échéant). Les bonus procurés par plusieurs objets de qualité supérieure ne s''additionnent pas.</p>', 1, 0, @res, NULL, @ddver),
  ('Sablier', @cae_materiel_de_classe_et_de_competence, 2500, NULL, 500, NULL, NULL, 150, NULL, 1, 0, @res, NULL, @ddver),
  ('Sacoche à composantes', @cae_materiel_de_classe_et_de_competence, 500, NULL, 1500, NULL, NULL, 160, '<p>On considère que tout jeteur de sorts en possédant une dispose des composantes matérielles et focaliseurs nécessaires à ses incantations, à trois exceptions près : les composantes ou focaliseurs dont le prix est indiqué dans la description du sort, les focaliseurs divins et ceux qui sont trop grands pour entrer dans la sacoche.</p>', 1, 0, @res, NULL, @ddver),
  ('Symbole sacré en argent', @cae_materiel_de_classe_et_de_competence, 2500, NULL, 500, NULL, NULL, 170, '<p>Un symbole sacré concentre l''énergie positive. Les prêtres et paladins s''en servent comme focaliseur pour leurs sorts, mais aussi pour repousser les morts-vivants. Chaque religion a son propre symbole.</p>', 1, 0, @res, NULL, @ddver),
  ('Symbole sacré en bois', @cae_materiel_de_classe_et_de_competence, 100, NULL, NULL, NULL, NULL, 180, '<p>Un symbole sacré concentre l''énergie positive. Les prêtres et paladins s''en servent comme focaliseur pour leurs sorts, mais aussi pour repousser les morts-vivants. Chaque religion a son propre symbole.</p>', 1, 0, @res, NULL, @ddver),
  ('Trousse de déguisement', @cae_materiel_de_classe_et_de_competence, 5000, NULL, 4000, NULL, NULL, 190, '<p>Ces outils idéaux confèrent un bonus de circonstances de +2 aux tests de Déguisement. Ses produits couvrent 10 utilisations seulement.</p>', 1, 0, @res, NULL, @ddver),
  ('Trousse de premiers secours', @cae_materiel_de_classe_et_de_competence, 5000, NULL, 500, NULL, NULL, 200, '<p>Ces outils idéaux confèrent un bonus de circonstances de +2 aux tests de Premiers secours. Ses produits couvrent 10 utilisations seulement.</p>', 1, 0, @res, NULL, @ddver);

-- vetements
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Costume d''artiste', @cae_vetements, 300, NULL, 2000, NULL, NULL, 10, '<p>Cette tenue voyante, parfois même criarde, donne l''air ridicule, mais elle permet en fait de danser, de multiplier les acrobaties, de marcher sur une corde raide, ou plus simplement de détaler à toutes jambes si le public réagit mal.</p>', 1, 0, @res, NULL, @ddver),
  ('Habit d''érudit', @cae_vetements, 500, NULL, 3000, NULL, NULL, 20, '<p>Robe, ceinture, casquette, chaussures souples et cape ou manteau (facultatif).</p>', 1, 0, @res, NULL, @ddver),
  ('Habit de cour', @cae_vetements, 3000, NULL, 3000, NULL, NULL, 30, '<p>Ces vêtements d''apparat suivent la mode du moment. Un personnage n''a presque aucune chance d''influencer nobles et autres gens de la cour en portant ses habits de tous les jours (malus de –2 sur les tests de compétence associés au Charisme joués pour influencer ces individus). Sans bijoux (un minimum de 50 po, à rajouter au prix des vêtements), il aura l''air d''un parvenu.</p>', 1, 0, @res, NULL, @ddver),
  ('Habit de moine', @cae_vetements, 500, NULL, 1000, NULL, NULL, 40, '<p>Cette tenue extrêmement simple se compose d''une paire de sandales, d''un pantalon et d''une chemise amples ceinturés avec des écharpes. Elle n''a l''air de rien mais est en fait conçue pour permettre une mobilité optimale à son porteur, et le tissu est de bonne qualité. Il est possible de ranger des armes dans les poches cachées dans les replis, et les écharpes sont suffisamment longues pour faire office de cordes.</p>', 1, 0, @res, NULL, @ddver),
  ('Habit de noble', @cae_vetements, 7500, NULL, 5000, NULL, NULL, 50, '<p>Cette tenue n''a qu''une seule fonction : montrer qu''elle a coûté les yeux de la tête. Gemmes et paillettes de métaux précieux sont incrustées dans le tissu. Pour s''intégrer à la société des nobles, il convient également de posséder une chevalière (voir <em>Matériel d''aventurier</em>) et des bijoux (pour une valeur minimale – ou apparente – de 100 po).</p>', 1, 0, @res, NULL, @ddver),
  ('Habit de paysan', @cae_vetements, 10, NULL, 1000, NULL, NULL, 60, '<p>Chemise ample et haut-de-chausse à l''avenant, ce dernier étant remplacé par une jupe pour les femmes. Les pieds sont protégés par plusieurs épaisseurs de tissu enroulé.</p>', 1, 0, @res, NULL, @ddver),
  ('Tenue d''artisan', @cae_vetements, 100, NULL, 2000, NULL, NULL, 70, '<p>Chemise à boutons, jupe ou pantalon retenu par une cordelette, chaussures, chapeau ou casquette (facultatif). Cette tenue peut également inclure un ceinturon ou un tablier (en cuir ou tissu) permettant de transporter des outils.</p>', 1, 0, @res, NULL, @ddver),
  ('Tenue d''explorateur', @cae_vetements, 1000, NULL, 4000, NULL, NULL, 80, '<p>Cette tenue extrêmement complète s''adresse aux gens qui ne savent jamais vraiment à quoi s''attendre. Elle comprend des bottes épaisses, des chausses ou une jupe en cuir, une ceinture, une chemise (à laquelle peut s''ajouter une veste ou un gilet), des gants et un manteau. Il est possible de remplacer la jupe en cuir par une tunique de même matière et une jupe en tissu. Ces habits sont pourvus de multiples poches (surtout le manteau). La tenue comprend également des objets variés pouvant se révéler utiles (écharpe, chapeau à large bord, etc.).</p>', 1, 0, @res, NULL, @ddver),
  ('Tenue de voyage', @cae_vetements, 100, NULL, 2500, NULL, NULL, 90, '<p>Bottes, jupe ou haut-de-chausse en laine, solide ceinturon, chemise (éventuellement agrémentée d''une veste ou d''un gilet), cape ou manteau à capuche.</p>', 1, 0, @res, NULL, @ddver),
  ('Tenue polaire', @cae_vetements, 800, NULL, 3500, NULL, NULL, 100, '<p>Cape en laine, chemise en lin, casquette en laine, épais manteau, pantalon ou jupe en velours et bottes. Une telle tenue procure un bonus de circonstances de +5 aux jets de Vigueur rendus nécessaires par un froid naturel particulièrement intense.</p>', 1, 0, @res, NULL, @ddver),
  ('Tenue sacerdotale', @cae_vetements, 500, NULL, 3000, NULL, NULL, 110, '<p>Ces vêtements sont conçus pour se livrer à diverses activités ou cérémonies religieuses, pas pour partir en aventure.</p>', 1, 0, @res, NULL, @ddver),
  ('Toilette royale', @cae_vetements, 20000, NULL, 7500, NULL, NULL, 120, '<p>Il s''agit des vêtements, pas des signes de la royauté que sont sceptre, couronne et autres. Particulièrement ostentatoires, ils ne sont que soieries, fourrures, gemmes et métaux précieux.</p>', 1, 0, @res, NULL, @ddver);

-- nourriture-boisson-et-hebergement
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Banquet (par convive)', @cae_nourriture_boisson_et_hebergement, 1000, NULL, NULL, NULL, NULL, 10, NULL, 1, 0, @res, NULL, @ddver),
  ('Bière, la chope', @cae_nourriture_boisson_et_hebergement, 4, NULL, 500, NULL, NULL, 20, NULL, 1, 0, @res, NULL, @ddver),
  ('Bière, le litre', @cae_nourriture_boisson_et_hebergement, 7, NULL, 1000, NULL, NULL, 30, NULL, 1, 0, @res, NULL, @ddver),
  ('Fromage, la portion', @cae_nourriture_boisson_et_hebergement, 10, NULL, 250, NULL, NULL, 40, NULL, 1, 0, @res, NULL, @ddver),
  ('Pain, la miche', @cae_nourriture_boisson_et_hebergement, 2, NULL, 250, NULL, NULL, 50, NULL, 1, 0, @res, NULL, @ddver),
  ('Repas de qualité médiocre (par jour)', @cae_nourriture_boisson_et_hebergement, 10, NULL, NULL, NULL, NULL, 60, '<p>Un repas médiocre peut être constitué de pain, de navets bouillis, d''oignon et d''eau.</p>', 1, 0, @res, NULL, @ddver),
  ('Repas de qualité convenable (par jour)', @cae_nourriture_boisson_et_hebergement, 30, NULL, NULL, NULL, NULL, 70, '<p>Pour un repas convenable, le menu se composera plutôt de pain, de ragoût de poulet, de carottes et de bière ou de vin coupés d''eau.</p>', 1, 0, @res, NULL, @ddver),
  ('Repas de bonne qualité (par jour)', @cae_nourriture_boisson_et_hebergement, 50, NULL, NULL, NULL, NULL, 80, '<p>Un bon repas pourra être le suivant : pain, bœuf, légumes verts, pâtisseries et bière ou vin.</p>', 1, 0, @res, NULL, @ddver),
  ('Séjour à l''auberge de qualité médiocre (par jour)', @cae_nourriture_boisson_et_hebergement, 20, NULL, NULL, NULL, NULL, 90, '<p>Une nuit médiocre à l''auberge prend la forme d''un petit coin de plancher près de l''âtre éteint.</p>', 1, 0, @res, NULL, @ddver),
  ('Séjour à l''auberge de qualité convenable (par jour)', @cae_nourriture_boisson_et_hebergement, 50, NULL, NULL, NULL, NULL, 100, '<p>Une prestation convenable permet de dormir dans un endroit chauffé et surélevé, avec une couverture et un oreiller, et en bien meilleure compagnie.</p>', 1, 0, @res, NULL, @ddver),
  ('Séjour à l''auberge de bonne qualité (par jour)', @cae_nourriture_boisson_et_hebergement, 200, NULL, NULL, NULL, NULL, 110, '<p>Un séjour de bonne qualité signifie une petite chambre personnelle à un seul lit, assortie du confort minimal et d''un pot de chambre couvert.</p>', 1, 0, @res, NULL, @ddver),
  ('Viande, la portion', @cae_nourriture_boisson_et_hebergement, 30, NULL, 500, NULL, NULL, 120, NULL, 1, 0, @res, NULL, @ddver),
  ('Vin de table (le pichet)', @cae_nourriture_boisson_et_hebergement, 20, NULL, 3000, NULL, NULL, 130, NULL, 1, 0, @res, NULL, @ddver),
  ('Vin de bon cru (la bouteille)', @cae_nourriture_boisson_et_hebergement, 1000, NULL, 750, NULL, NULL, 140, NULL, 1, 0, @res, NULL, @ddver);

-- montures-et-harnachement
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Âne ou mulet', @cae_montures_et_harnachement, 800, NULL, NULL, NULL, NULL, 10, '<p>Peu craintifs, ils ont le pied sûr et s''avèrent capables de porter de lourdes charges sur de longues distances. Contrairement au cheval, ils acceptent de pénétrer dans les catacombes et autres lieux dangereux, bien que cela ne leur fasse guère plaisir.</p>', 1, 0, @res, NULL, @ddver),
  ('Barde pour créature de taille moyenne', @cae_montures_et_harnachement, NULL, '×2 le prix de l''armure', NULL, '×1 le poids de l''armure', NULL, 20, '<p>La barde est l''armure qui protège la tête, le cou, le poitrail, le corps et parfois les jambes d''un cheval. Il existe à peu près autant de bardes différentes que d''armures (voir la liste des armures et boucliers). Une barde correspondant à une armure intermédiaire ou lourde protège mieux, mais la vitesse de la monture s''en ressent.</p><p>Le cheval étant une créature de taille G et non humanoïde, son armure coûte quatre fois plus cher que celle d''un humain (une créature de taille M) et son poids est le double des chiffres mentionnés pour les armures (voir <em>Armures pour créatures inhabituelles</em>). Dans le cas où la barde est censée équiper un poney ou toute autre monture de taille M, son poids est le même que celui indiqué pour un humanoïde de taille M et son coût est seulement doublé.</p><p>Les bardes lourdes ou intermédiaires ralentissent les montures. Les montures volantes sont incapables de décoller si elles sont lestées par une barde lourde ou intermédiaire. Mettre ou enlever une barde prend cinq fois plus de temps que ne l''indique la table pour enfiler ou ôter une armure. Un animal en armure ne peut transporter d''autre charge que son cavalier et ses fontes. C''est pour cette raison que les chevaliers ont souvent besoin d''un second animal pour transporter leur équipement.</p>', 1, 0, @res, NULL, @ddver),
  ('Barde pour créature de grande taille', @cae_montures_et_harnachement, NULL, '×4 le prix de l''armure', NULL, '×2 le poids de l''armure', NULL, 30, '<p>La barde est l''armure qui protège la tête, le cou, le poitrail, le corps et parfois les jambes d''un cheval. Il existe à peu près autant de bardes différentes que d''armures (voir la liste des armures et boucliers). Une barde correspondant à une armure intermédiaire ou lourde protège mieux, mais la vitesse de la monture s''en ressent.</p><p>Le cheval étant une créature de taille G et non humanoïde, son armure coûte quatre fois plus cher que celle d''un humain (une créature de taille M) et son poids est le double des chiffres mentionnés pour les armures (voir <em>Armures pour créatures inhabituelles</em>). Dans le cas où la barde est censée équiper un poney ou toute autre monture de taille M, son poids est le même que celui indiqué pour un humanoïde de taille M et son coût est seulement doublé.</p><p>Les bardes lourdes ou intermédiaires ralentissent les montures. Les montures volantes sont incapables de décoller si elles sont lestées par une barde lourde ou intermédiaire. Mettre ou enlever une barde prend cinq fois plus de temps que ne l''indique la table pour enfiler ou ôter une armure. Un animal en armure ne peut transporter d''autre charge que son cavalier et ses fontes. C''est pour cette raison que les chevaliers ont souvent besoin d''un second animal pour transporter leur équipement.</p>', 1, 0, @res, NULL, @ddver),
  ('Destrier léger', @cae_montures_et_harnachement, 15000, NULL, NULL, NULL, NULL, 40, '<p>Destriers et poneys de guerre ne rechignent pas au combat. À l''inverse, poneys et chevaux lourds ou légers sont durs à contrôler dans une telle situation.</p>
<p>Le cheval est parfait pour les elfes, demi-elfes, demi-orques, humains et nains. Le poney, plus petit, convient plutôt aux gnomes et halfelins.</p>', 1, 0, @res, NULL, @ddver),
  ('Destrier lourd', @cae_montures_et_harnachement, 40000, NULL, NULL, NULL, NULL, 50, '<p>Destriers et poneys de guerre ne rechignent pas au combat. À l''inverse, poneys et chevaux lourds ou légers sont durs à contrôler dans une telle situation.</p>
<p>Le cheval est parfait pour les elfes, demi-elfes, demi-orques, humains et nains. Le poney, plus petit, convient plutôt aux gnomes et halfelins.</p>', 1, 0, @res, NULL, @ddver),
  ('Cheval léger', @cae_montures_et_harnachement, 7500, NULL, NULL, NULL, NULL, 60, '<p>Destriers et poneys de guerre ne rechignent pas au combat. À l''inverse, poneys et chevaux lourds ou légers sont durs à contrôler dans une telle situation.</p>
<p>Le cheval est parfait pour les elfes, demi-elfes, demi-orques, humains et nains. Le poney, plus petit, convient plutôt aux gnomes et halfelins.</p>', 1, 0, @res, NULL, @ddver),
  ('Cheval lourd', @cae_montures_et_harnachement, 20000, NULL, NULL, NULL, NULL, 70, '<p>Destriers et poneys de guerre ne rechignent pas au combat. À l''inverse, poneys et chevaux lourds ou légers sont durs à contrôler dans une telle situation.</p>
<p>Le cheval est parfait pour les elfes, demi-elfes, demi-orques, humains et nains. Le poney, plus petit, convient plutôt aux gnomes et halfelins.</p>', 1, 0, @res, NULL, @ddver),
  ('Poney', @cae_montures_et_harnachement, 3000, NULL, NULL, NULL, NULL, 80, '<p>Le cheval est parfait pour les elfes, demi-elfes, demi-orques, humains et nains. Le poney, plus petit, convient plutôt aux gnomes et halfelins.</p>', 1, 0, @res, NULL, @ddver),
  ('Poney de guerre', @cae_montures_et_harnachement, 10000, NULL, NULL, NULL, NULL, 90, '<p>Destriers et poneys de guerre ne rechignent pas au combat. À l''inverse, poneys et chevaux lourds ou légers sont durs à contrôler dans une telle situation.</p>
<p>Le cheval est parfait pour les elfes, demi-elfes, demi-orques, humains et nains. Le poney, plus petit, convient plutôt aux gnomes et halfelins.</p>', 1, 0, @res, NULL, @ddver),
  ('Chien de garde', @cae_montures_et_harnachement, 2500, NULL, NULL, NULL, NULL, 100, NULL, 1, 0, @res, NULL, @ddver),
  ('Chien de selle', @cae_montures_et_harnachement, 15000, NULL, NULL, NULL, NULL, 110, '<p>Ce chien de taille M a été dressé à porter un humanoïde de taille P (et pas un nain). Au combat, il se montre aussi brave qu''un destrier. On ne subit aucun dégât en tombant depuis un chien de selle.</p>', 1, 0, @res, NULL, @ddver),
  ('Écurie (pour une journée)', @cae_montures_et_harnachement, 50, NULL, NULL, NULL, NULL, 120, '<p>Indique le prix d''une journée passée à l''écurie. Nourriture et soins de l''animal sont inclus.</p>', 1, 0, @res, NULL, @ddver),
  ('Fontes', @cae_montures_et_harnachement, 400, NULL, 4000, NULL, NULL, 130, NULL, 1, 0, @res, NULL, @ddver),
  ('Mors et bride', @cae_montures_et_harnachement, 200, NULL, 500, NULL, NULL, 140, NULL, 1, 0, @res, NULL, @ddver),
  ('Nourriture pour animaux (par jour)', @cae_montures_et_harnachement, 5, NULL, 5000, NULL, NULL, 150, '<p>Chevaux, ânes, mulets ou poneys peuvent se nourrir en paissant, mais il vaut mieux leur acheter une nourriture plus énergétique. Un chien de selle doit manger de la viande chaque jour.</p>', 1, 0, @res, NULL, @ddver),
  ('Selle d''équitation', @cae_montures_et_harnachement, 1000, NULL, 12500, NULL, NULL, 160, '<p>Cette selle de modèle courant est faite pour accueillir un cavalier.</p>', 1, 0, @res, NULL, @ddver),
  ('Selle de bât', @cae_montures_et_harnachement, 500, NULL, 7500, NULL, NULL, 170, '<p>Cette selle est conçue pour y accrocher équipement et provisions, pas un cavalier. On peut y fixer l''intégralité de la charge acceptée par la monture.</p>', 1, 0, @res, NULL, @ddver),
  ('Selle de guerre', @cae_montures_et_harnachement, 2000, NULL, 15000, NULL, NULL, 180, '<p>La selle de guerre remonte sur l''avant et l''arrière, pour offrir une meilleure assise au cavalier. Ce dernier bénéficie d''un bonus de circonstances de +2 à tous les tests d''Équitation visant à déterminer s''il reste en selle. Même s''il perd connaissance, il a 75 % de chances de rester sur sa monture (contre 50 % seulement avec une selle d''équitation normale).</p>', 1, 0, @res, NULL, @ddver),
  ('Selle spéciale d''équitation', @cae_montures_et_harnachement, 3000, NULL, 15000, NULL, NULL, 190, '<p>Une selle spéciale correspond à une selle normale de même modèle, si ce n''est qu''elle est destinée à une monture inhabituelle. Il en existe trois modèles : selle d''équitation, de bât ou de guerre.</p>', 1, 0, @res, NULL, @ddver),
  ('Selle spéciale de bât', @cae_montures_et_harnachement, 1500, NULL, 10000, NULL, NULL, 200, '<p>Une selle spéciale correspond à une selle normale de même modèle, si ce n''est qu''elle est destinée à une monture inhabituelle. Il en existe trois modèles : selle d''équitation, de bât ou de guerre.</p>', 1, 0, @res, NULL, @ddver),
  ('Selle spéciale de guerre', @cae_montures_et_harnachement, 6000, NULL, 20000, NULL, NULL, 210, '<p>Une selle spéciale correspond à une selle normale de même modèle, si ce n''est qu''elle est destinée à une monture inhabituelle. Il en existe trois modèles : selle d''équitation, de bât ou de guerre.</p>', 1, 0, @res, NULL, @ddver);

-- moyens-de-transport
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Barque', @cae_moyens_de_transport, 5000, NULL, 50000, NULL, NULL, 10, '<p>Cette embarcation de 2,50 à 3,50 mètres de long peut accueillir deux ou trois passagers de taille M. Elle se déplace à une vitesse de 2,25 km par heure.</p>', 1, 0, @res, NULL, @ddver),
  ('Rame', @cae_moyens_de_transport, 200, NULL, 5000, NULL, NULL, 20, NULL, 1, 0, @res, NULL, @ddver),
  ('Bateau à fond plat', @cae_moyens_de_transport, 300000, NULL, NULL, NULL, NULL, 30, '<p>Ce bateau est long de 15 à 22 mètres et large de 4,50 à 6 mètres. Il possède un seul mât à voile carrée et quelques rames. Son équipage est composé de 8 à 15 marins et il peut transporter une cargaison de 40 à 50 tonnes ou une troupe de 100 soldats. Son fond plat lui permet de remonter les cours d''eau et d''effectuer des sorties en mer. Sa vitesse est de 1,5 km par heure.</p>', 1, 0, @res, NULL, @ddver),
  ('Carriole', @cae_moyens_de_transport, 10000, NULL, 300000, NULL, NULL, 40, '<p>Ce véhicule à quatre roues peut transporter jusqu''à quatre personnes dans un compartiment fermé, plus deux conducteurs. En général, elle est tirée par deux chevaux (ou d''autres bêtes de somme). Une carriole est vendue avec ses harnais.</p>', 1, 0, @res, NULL, @ddver),
  ('Chariot', @cae_moyens_de_transport, 3500, NULL, 200000, NULL, NULL, 50, '<p>Ce véhicule ouvert à quatre roues est conçu pour transporter de lourdes cargaisons. Deux chevaux (ou autres bêtes de somme) sont nécessaires pour le tirer. Il est fourni avec le harnais d''attelage.</p>', 1, 0, @res, NULL, @ddver),
  ('Charrette', @cae_moyens_de_transport, 1500, NULL, 100000, NULL, NULL, 60, '<p>Ce véhicule à deux roues est tiré par un seul cheval (ou autre bête de somme). Les harnais sont fournis.</p>', 1, 0, @res, NULL, @ddver),
  ('Drakkar', @cae_moyens_de_transport, 1000000, NULL, NULL, NULL, NULL, 70, '<p>Ce navire élancé, long d''un peu plus de 20 mètres, s''accompagne de 40 rames et de 50 hommes d''équipage. Il possède un seul mât à voile carrée et peut transporter une cargaison de 50 tonnes ou 120 soldats. Un drakkar peut naviguer en mer. Il file à une vitesse de 4,5 km par heure, qu''on le propulse à la rame ou à l''aide de sa voile.</p>', 1, 0, @res, NULL, @ddver),
  ('Navire de haute mer', @cae_moyens_de_transport, 1000000, NULL, NULL, NULL, NULL, 80, '<p>Ce bateau plus grand qu''une trirème est destiné à naviguer en mer. Il mesure entre 22,5 et 27 mètres de long et 6 mètres de large. Il accueille 20 marins. Il peut transporter une cargaison de 150 tonnes. Ses deux mâts portent des voiles carrées. Il se déplace à 3 km par heure.</p>', 1, 0, @res, NULL, @ddver),
  ('Traîneau', @cae_moyens_de_transport, 2000, NULL, 150000, NULL, NULL, 90, '<p>Ce chariot est monté sur des skis (à la place de roues) qui lui permettent de se déplacer sur la neige ou la glace. En règle générale, deux chevaux (ou autres bêtes de somme) sont nécessaires pour le tirer. Il est fourni avec le harnais d''attelage.</p>', 1, 0, @res, NULL, @ddver),
  ('Trirème', @cae_moyens_de_transport, 3000000, NULL, NULL, NULL, NULL, 100, '<p>Ce grand trois-mâts possède 70 rames par bord et rassemble 200 hommes d''équipage. Long de 40 mètres et large de 6, il peut transporter jusqu''à 150 tonnes de cargaison ou 250 soldats. Pour 8 000 po de plus, il est possible de l''équiper d''un bélier fixé à l''étrave et de trois châteaux disposés à l''avant, à l''arrière et à mi-longueur, destinés à accueillir des machines de guerre. Incapable de braver la haute mer, la trirème ne peut s''éloigner des côtes. Sa vitesse de pointe est la même qu''elle soit poussée par le vent ou propulsée par ses rames, soit 6 km par heure.</p>', 1, 0, @res, NULL, @ddver),
  ('Vaisseau de guerre', @cae_moyens_de_transport, 2500000, NULL, NULL, NULL, NULL, 110, '<p>Ce bâtiment de 30 mètres de long possède un seul mât, ainsi que des rames. Son équipage est composé de 60 à 80 rameurs. Ce navire peut transporter 160 soldats, mais pas pour de longues distances car il n''y a pas assez d''espace pour les vivres nécessaires à nourrir autant de personnes. Le vaisseau de guerre ne peut naviguer en haute mer et se contente de suivre les côtes. Il n''est pas utilisé pour le transport de cargaisons. Il se déplace à 3,75 km par heure quel que soit son mode de propulsion.</p>', 1, 0, @res, NULL, @ddver);

-- services
INSERT INTO dd_equipements (eqt_nom, eqt_cae_id, eqt_prix_pc, eqt_prix_txt, eqt_poids_g, eqt_poids_txt,
  eqt_attributs, eqt_ordre, eqt_description, eqt_visible, eqt_public, eqt_res_id, eqt_camp_id, eqt_ruleset_var_id) VALUES
  ('Diligence', @cae_services, NULL, '3 pc par 1,5 km', NULL, NULL, NULL, 10, '<p>Le prix indiqué concerne le trajet effectué à bord d''une diligence qui transporte des personnes et une cargaison légère entre deux villes. À l''intérieur des cités, une calèche peut vous emmener à peu près n''importe où pour une pièce de cuivre.</p>', 1, 0, @res, NULL, @ddver),
  ('Droit de passage ou d''entrée', @cae_services, 1, NULL, NULL, NULL, NULL, 20, '<p>Certaines grandes routes s''accompagnent d''un péage, ou droit de passage, permettant de payer leur entretien et le salaire des soldats qui y patrouillent. De la même manière, quelques villes fortifiées exigent un droit d''entrée (ainsi, parfois, qu''un droit de sortie).</p>', 1, 0, @res, NULL, @ddver),
  ('Employé qualifié', @cae_services, NULL, '3 pa par jour', NULL, NULL, NULL, 30, '<p>Le montant indiqué correspond à une journée de salaire moyen pour des mercenaires, des maçons, des artisans, des scribes, des conducteurs d''attelages et d''autres fonctions nécessitant une compétence. Cette valeur est un salaire minimum, certains employés se font payer beaucoup plus.</p>', 1, 0, @res, NULL, @ddver),
  ('Employé non qualifié', @cae_services, NULL, '1 pa par jour', NULL, NULL, NULL, 40, '<p>Le montant indiqué correspond à une journée de salaire moyen pour un manœuvre, un portier, un cuisinier, une femme de chambre ou pour un autre travail laborieux.</p>', 1, 0, @res, NULL, @ddver),
  ('Messager', @cae_services, NULL, '2 pc par 1,5 km', NULL, NULL, NULL, 50, '<p>Cette catégorie comprend les messagers se déplaçant à pied ou à cheval. Si l''individu doit de toutes façons se rendre au lieu où il faut porter le message, il peut éventuellement demander deux fois moins.</p>', 1, 0, @res, NULL, @ddver),
  ('Sort de niveau 0', @cae_services, NULL, 'Niveau × 5 po', NULL, NULL, NULL, 60, '<p>Le prix indiqué est celui qu''il faut payer pour qu''un PNJ accepte de jeter le sort demandé (voir <em>Lancement de sorts et services</em>). Le niveau de cette formule est le niveau de lanceur de sorts. Voir la description du sort pour les coûts additionnels. En règle générale, si les surcoûts d''un sort amènent son coût au-delà de 3 000 po, il n''est pas disponible sauf permission expresse du MJ.</p>', 1, 0, @res, NULL, @ddver),
  ('Sort de 1er niveau', @cae_services, NULL, 'Niveau × 10 po', NULL, NULL, NULL, 70, '<p>Le prix indiqué est celui qu''il faut payer pour qu''un PNJ accepte de jeter le sort demandé (voir <em>Lancement de sorts et services</em>). Le niveau de cette formule est le niveau de lanceur de sorts. Voir la description du sort pour les coûts additionnels. En règle générale, si les surcoûts d''un sort amènent son coût au-delà de 3 000 po, il n''est pas disponible sauf permission expresse du MJ.</p>', 1, 0, @res, NULL, @ddver),
  ('Sort de 2e niveau', @cae_services, NULL, 'Niveau × 20 po', NULL, NULL, NULL, 80, '<p>Le prix indiqué est celui qu''il faut payer pour qu''un PNJ accepte de jeter le sort demandé (voir <em>Lancement de sorts et services</em>). Le niveau de cette formule est le niveau de lanceur de sorts. Voir la description du sort pour les coûts additionnels. En règle générale, si les surcoûts d''un sort amènent son coût au-delà de 3 000 po, il n''est pas disponible sauf permission expresse du MJ.</p>', 1, 0, @res, NULL, @ddver),
  ('Sort de 3e niveau', @cae_services, NULL, 'Niveau × 30 po', NULL, NULL, NULL, 90, '<p>Le prix indiqué est celui qu''il faut payer pour qu''un PNJ accepte de jeter le sort demandé (voir <em>Lancement de sorts et services</em>). Le niveau de cette formule est le niveau de lanceur de sorts. Voir la description du sort pour les coûts additionnels. En règle générale, si les surcoûts d''un sort amènent son coût au-delà de 3 000 po, il n''est pas disponible sauf permission expresse du MJ.</p>', 1, 0, @res, NULL, @ddver),
  ('Sort de 4e niveau', @cae_services, NULL, 'Niveau × 40 po', NULL, NULL, NULL, 100, '<p>Le prix indiqué est celui qu''il faut payer pour qu''un PNJ accepte de jeter le sort demandé (voir <em>Lancement de sorts et services</em>). Le niveau de cette formule est le niveau de lanceur de sorts. Voir la description du sort pour les coûts additionnels. En règle générale, si les surcoûts d''un sort amènent son coût au-delà de 3 000 po, il n''est pas disponible sauf permission expresse du MJ.</p>', 1, 0, @res, NULL, @ddver),
  ('Sort de 5e niveau', @cae_services, NULL, 'Niveau × 50 po', NULL, NULL, NULL, 110, '<p>Le prix indiqué est celui qu''il faut payer pour qu''un PNJ accepte de jeter le sort demandé (voir <em>Lancement de sorts et services</em>). Le niveau de cette formule est le niveau de lanceur de sorts. Voir la description du sort pour les coûts additionnels. En règle générale, si les surcoûts d''un sort amènent son coût au-delà de 3 000 po, il n''est pas disponible sauf permission expresse du MJ.</p>', 1, 0, @res, NULL, @ddver),
  ('Sort de 6e niveau', @cae_services, NULL, 'Niveau × 60 po', NULL, NULL, NULL, 120, '<p>Le prix indiqué est celui qu''il faut payer pour qu''un PNJ accepte de jeter le sort demandé (voir <em>Lancement de sorts et services</em>). Le niveau de cette formule est le niveau de lanceur de sorts. Voir la description du sort pour les coûts additionnels. En règle générale, si les surcoûts d''un sort amènent son coût au-delà de 3 000 po, il n''est pas disponible sauf permission expresse du MJ.</p>', 1, 0, @res, NULL, @ddver),
  ('Sort de 7e niveau', @cae_services, NULL, 'Niveau × 70 po', NULL, NULL, NULL, 130, '<p>Le prix indiqué est celui qu''il faut payer pour qu''un PNJ accepte de jeter le sort demandé (voir <em>Lancement de sorts et services</em>). Le niveau de cette formule est le niveau de lanceur de sorts. Voir la description du sort pour les coûts additionnels. En règle générale, si les surcoûts d''un sort amènent son coût au-delà de 3 000 po, il n''est pas disponible sauf permission expresse du MJ.</p>', 1, 0, @res, NULL, @ddver),
  ('Sort de 8e niveau', @cae_services, NULL, 'Niveau × 80 po', NULL, NULL, NULL, 140, '<p>Le prix indiqué est celui qu''il faut payer pour qu''un PNJ accepte de jeter le sort demandé (voir <em>Lancement de sorts et services</em>). Le niveau de cette formule est le niveau de lanceur de sorts. Voir la description du sort pour les coûts additionnels. En règle générale, si les surcoûts d''un sort amènent son coût au-delà de 3 000 po, il n''est pas disponible sauf permission expresse du MJ.</p>', 1, 0, @res, NULL, @ddver),
  ('Sort de 9e niveau', @cae_services, NULL, 'Niveau × 90 po', NULL, NULL, NULL, 150, '<p>Le prix indiqué est celui qu''il faut payer pour qu''un PNJ accepte de jeter le sort demandé (voir <em>Lancement de sorts et services</em>). Le niveau de cette formule est le niveau de lanceur de sorts. Voir la description du sort pour les coûts additionnels. En règle générale, si les surcoûts d''un sort amènent son coût au-delà de 3 000 po, il n''est pas disponible sauf permission expresse du MJ.</p>', 1, 0, @res, NULL, @ddver),
  ('Traversée en bateau', @cae_services, NULL, '1 pa par 1,5 km', NULL, NULL, NULL, 160, '<p>La plupart des navires sont conçus pour d''autres fonctions que le transport des passagers, mais ils ont souvent la possibilité d''en accueillir quelques-uns en plus de leur cargaison. Le prix indiqué doit être doublé pour les créatures de taille G ou plus grande, ainsi que pour les créatures qu''il est pour une raison ou une autre difficile à amener sur un bateau.</p>', 1, 0, @res, NULL, @ddver);

COMMIT;
